void _paintPine(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  c.drawRect(Rect.fromLTWH(r.center.dx - w * 0.06, r.bottom - h * 0.16, w * 0.12, h * 0.16), Pk.fill(const Color(0xFF7A4E30)));
  for (var i = 0; i < 3; i++) {
    final top = r.top + h * (i * 0.24);
    final base = r.top + h * (0.36 + i * 0.24);
    final half = w * (0.26 + i * 0.12);
    Pk.poly(c, [Offset(r.center.dx - half, base), Offset(r.center.dx, top), Offset(r.center.dx + half, base)], Pk.fill(i.isEven ? a : Pk.dark(a, 0.08)));
    Pk.poly(c, [Offset(r.center.dx, top), Offset(r.center.dx + half, base), Offset(r.center.dx, base)], Pk.fill(Pk.dark(a, 0.15)));
    final snow = Path()
      ..moveTo(r.center.dx - half * 0.55, top + (base - top) * 0.55)
      ..lineTo(r.center.dx, top)
      ..lineTo(r.center.dx + half * 0.55, top + (base - top) * 0.55)
      ..quadraticBezierTo(r.center.dx, top + (base - top) * 0.4, r.center.dx - half * 0.55, top + (base - top) * 0.55);
    c.drawPath(snow, Pk.fill(b));
  }
}

void _paintAurora(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  for (var band = 0; band < 2; band++) {
    final col = band == 0 ? a : b;
    for (var i = 0; i <= 44; i++) {
      final k = i / 44;
      final x = r.left + w * k;
      final y = r.top + h * (0.3 + 0.22 * sin(k * 5.5 + t * 0.5 + band * 1.7)) + band * h * 0.12;
      final len = h * (0.35 + 0.2 * sin(k * 9 + t + band));
      final ray = Rect.fromLTWH(x - 2.5, y, 5, len);
      c.drawRect(ray, _vgrad(ray, col.withValues(alpha: 0.55), col.withValues(alpha: 0)));
    }
  }
}

