void _iceGateScenery(Canvas c, double ov, double t) {
  for (final (x, hh, ww) in [(-30.0, 90.0, 170.0), (250.0, 100.0, 190.0)]) {
    final peak = Offset(x + ww / 2, 146 - hh);
    Pk.poly(c, [Offset(x, 146), peak, Offset(x + ww, 146)], Pk.fill(Pk.mix(const Color(0xFFA8B0BA), const Color(0xFFA9C8EE), ov)));
    Pk.poly(c, [peak + Offset(-ww * 0.16, hh * 0.32), peak, peak + Offset(ww * 0.16, hh * 0.32)], Pk.fill(Colors.white));
  }
  final ice = Pk.mix(const Color(0xFFB7C3CC), const Color(0xFFDDF3FF), ov);
  c.drawRect(const Rect.fromLTWH(0, 92, 400, 56), Pk.fill(ice));
  for (var y = 0; y < 3; y++) {
    for (var x = 0; x < 11; x++) {
      c.drawRect(Rect.fromLTWH(x * 40.0 - (y.isOdd ? 20 : 0), 92 + y * 18.0, 40, 18), Pk.stroke(Pk.dark(ice, 0.12), 1));
    }
  }
  for (var i = 0; i < 20; i++) {
    c.drawRect(Rect.fromLTWH(i * 20.0 + 3, 84, 12, 9), Pk.fill(Pk.light(ice, 0.2)));
  }
  c.drawRect(const Rect.fromLTWH(0, 90, 400, 3), Pk.fill(Colors.white));
  for (var i = 0; i < 18; i++) {
    final x = (Pk.rand(i + 3) * 420 + t * (6 + Pk.rand(i) * 6)) % 420 - 10;
    final y = (Pk.rand(i + 11) * 240 + t * (14 + Pk.rand(i + 5) * 10)) % 240;
    c.drawCircle(Offset(x, y), 1 + Pk.rand(i + 2) * 1.2, Pk.fill(Colors.white.withValues(alpha: 0.75)));
  }
}

void _iceHall(Canvas c, double ov, double t) {
  final line = Pk.stroke(Colors.white.withValues(alpha: 0.18 + 0.2 * ov), 1);
  for (var y = 0; y < 8; y++) {
    c.drawLine(Offset(0, 20 + y * 20.0), Offset(400, 20 + y * 20.0), line);
    for (var x = 0; x < 9; x++) {
      final xx = x * 50.0 + (y.isOdd ? 25 : 0);
      c.drawLine(Offset(xx, 20 + y * 20.0), Offset(xx, 40 + y * 20.0), line);
    }
  }
  for (var i = 0; i < 6; i++) {
    final x = 30 + i * 68.0;
    final p = Offset(x, 30 + Pk.rand(i) * 100);
    Pk.sparkle(c, p, (1.5 + 1.5 * sin(t * 2 + i)) * ov, Colors.white);
  }
}

void _snowHills(Canvas c, double ov, double t) {
