  final palace = Pk.mix(const Color(0xFF9EA8B0), const Color(0xFFB8DDF5), ov);
  for (final (x, w, hh) in [(150.0, 22.0, 70.0), (176.0, 48.0, 50.0), (228.0, 22.0, 70.0)]) {
    c.drawRect(Rect.fromLTWH(x, 132 - hh, w, hh), Pk.fill(palace));
    Pk.poly(c, [Offset(x - 3, 132 - hh), Offset(x + w / 2, 132 - hh - w * 0.9), Offset(x + w + 3, 132 - hh)], Pk.fill(Pk.light(palace, 0.2)));
  }
  final hills = Path()
    ..moveTo(0, 130)
    ..quadraticBezierTo(80, 104, 170, 126)
    ..quadraticBezierTo(270, 100, 400, 122)
    ..lineTo(400, 150)
    ..lineTo(0, 150)
    ..close();
  c.drawPath(hills, Pk.fill(far));
  for (var i = 0; i < 16; i++) {
    final x = (Pk.rand(i + 3) * 420 + t * (5 + Pk.rand(i) * 5)) % 420 - 10;
    final y = (Pk.rand(i + 11) * 240 + t * (12 + Pk.rand(i + 5) * 8)) % 240;
    c.drawCircle(Offset(x, y), 1 + Pk.rand(i + 2), Pk.fill(Colors.white.withValues(alpha: 0.8)));
  }
}

void _auroraBalcony(Canvas c, double ov, double t) {
  final far = Pk.mix(const Color(0xFF4A4E66), const Color(0xFF2E4A7A), ov);
  final near = Pk.mix(const Color(0xFF5E6278), const Color(0xFF3E6A9A), ov);
  Pk.poly(c, const [Offset(-20, 150), Offset(60, 92), Offset(130, 132), Offset(200, 84), Offset(290, 136), Offset(350, 98), Offset(420, 150)], Pk.fill(far));
  for (final p in const [Offset(60, 92), Offset(200, 84), Offset(350, 98)]) {
    Pk.poly(c, [p + const Offset(-14, 12), p, p + const Offset(14, 12)], Pk.fill(Colors.white.withValues(alpha: 0.85)));
  }
  final hills = Path()
    ..moveTo(0, 140)
    ..quadraticBezierTo(120, 118, 220, 138)
    ..quadraticBezierTo(320, 124, 400, 136)
    ..lineTo(400, 152)
    ..lineTo(0, 152)
    ..close();
  c.drawPath(hills, Pk.fill(near));
  final stone = Pk.mix(const Color(0xFF8A8E9A), const Color(0xFFDDEBFF), ov);
  c.drawRect(const Rect.fromLTWH(0, 148, 400, 6), Pk.fill(Pk.light(stone, 0.2)));
  c.drawRect(const Rect.fromLTWH(0, 124, 400, 6), Pk.fill(Pk.light(stone, 0.25)));
  for (var i = 0; i < 21; i++) {
    final x = i * 20.0 + 4;
    c.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(x, 130, 10, 18), const Radius.circular(4)), Pk.fill(stone));
  }
  c.drawRect(const Rect.fromLTWH(0, 121, 400, 4), Pk.fill(Colors.white));
}

// =============================================================== HOT SPRINGS

void _paintStoneSteps(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  const n = 6;
  for (var i = n - 1; i >= 0; i--) {
    final k0 = i / n, k1 = (i + 1) / n;
    final y0 = r.bottom - h * k1, y1 = r.bottom - h * k0;
    final half0 = w * (0.5 - 0.3 * k1), half1 = w * (0.5 - 0.3 * k0);
    final cx = r.center.dx + sin(i * 0.9) * w * 0.06;
    Pk.poly(c, [Offset(cx - half1, y1), Offset(cx - half0, y0), Offset(cx + half0, y0), Offset(cx + half1, y1)], Pk.fill(i.isEven ? a : Pk.dark(a, 0.06)));
    c.drawLine(Offset(cx - half1, y1), Offset(cx + half1, y1), Pk.stroke(Pk.dark(a, 0.3), 2));
    c.drawOval(Rect.fromCenter(center: Offset(cx - half1 * 0.7, y1 - 2), width: w * 0.08, height: 4), Pk.fill(b));
  }
}

void _paintTorii(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  for (final x in [0.18, 0.82]) {
    final px = r.left + w * x;
    c.drawRect(Rect.fromLTWH(px - w * 0.05, r.top + h * 0.14, w * 0.1, h * 0.86), Pk.fill(a));
    c.drawRect(Rect.fromLTWH(px - w * 0.065, r.bottom - h * 0.08, w * 0.13, h * 0.08), Pk.fill(b));
  }
  Pk.box(c, Rect.fromLTWH(r.left + w * 0.08, r.top + h * 0.28, w * 0.84, h * 0.07), a, radius: 1);
  final top = Path()
    ..moveTo(r.left - w * 0.02, r.top + h * 0.02)
    ..quadraticBezierTo(r.center.dx, r.top + h * 0.12, r.right + w * 0.02, r.top + h * 0.02)
    ..lineTo(r.right - w * 0.04, r.top + h * 0.16)
    ..quadraticBezierTo(r.center.dx, r.top + h * 0.22, r.left + w * 0.04, r.top + h * 0.16)
    ..close();
  c.drawPath(top, Pk.fill(a));
  final cap = Path()
    ..moveTo(r.left - w * 0.04, r.top - h * 0.02)
    ..quadraticBezierTo(r.center.dx, r.top + h * 0.08, r.right + w * 0.04, r.top - h * 0.02)
    ..lineTo(r.right + w * 0.02, r.top + h * 0.04)
    ..quadraticBezierTo(r.center.dx, r.top + h * 0.13, r.left - w * 0.02, r.top + h * 0.04)
    ..close();
  c.drawPath(cap, Pk.fill(b));
  c.drawRect(Rect.fromLTWH(r.center.dx - w * 0.05, r.top + h * 0.14, w * 0.1, h * 0.14), Pk.fill(a));
}

void _paintStoneLantern(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  Pk.box(c, Rect.fromLTWH(r.left + w * 0.15, r.bottom - h * 0.1, w * 0.7, h * 0.1), Pk.dark(a, 0.1), radius: 2);
  c.drawRect(Rect.fromLTWH(r.center.dx - w * 0.12, r.top + h * 0.5, w * 0.24, h * 0.42), Pk.fill(a));
  Pk.box(c, Rect.fromLTWH(r.left + w * 0.1, r.top + h * 0.46, w * 0.8, h * 0.07), Pk.dark(a, 0.05), radius: 2);
  final light = Rect.fromLTWH(r.left + w * 0.2, r.top + h * 0.27, w * 0.6, h * 0.2);
  c.drawRect(light, Pk.fill(Pk.dark(a, 0.15)));
  Pk.glow(c, light.center, w * 0.9, b, 0.5 + 0.1 * sin(t * 4 + r.left));
  c.drawRect(light.deflate(w * 0.1), Pk.fill(b));
  Pk.poly(c, [Offset(r.left - w * 0.05, r.top + h * 0.3), Offset(r.left + w * 0.25, r.top + h * 0.12), Offset(r.right - w * 0.25, r.top + h * 0.12), Offset(r.right + w * 0.05, r.top + h * 0.3)], Pk.fill(Pk.light(a, 0.1)));
  c.drawCircle(Offset(r.center.dx, r.top + h * 0.08), w * 0.1, Pk.fill(Pk.light(a, 0.1)));
}

void _paintPaperLantern(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  final sway = sin(t * 1.3 + r.left) * w * 0.05;
  c.drawLine(r.topCenter, Offset(r.center.dx + sway, r.top + h * 0.2), Pk.stroke(const Color(0xFF3B3452), 1));
  final body = Rect.fromLTWH(r.left + sway, r.top + h * 0.24, w, h * 0.62);
  Pk.glow(c, body.center, w * 1.5, b, 0.5);
  c.drawOval(body, Pk.fill(a));
  for (var i = 1; i < 4; i++) {
    final y = body.top + body.height * i / 4;
    c.drawLine(Offset(body.left + w * 0.08, y), Offset(body.right - w * 0.08, y), Pk.stroke(Pk.dark(a, 0.18), 0.8));
  }
  c.drawOval(Rect.fromCenter(center: body.center, width: w * 0.45, height: body.height * 0.6), Pk.fill(Colors.white.withValues(alpha: 0.35)));
  c.drawRect(Rect.fromLTWH(body.center.dx - w * 0.25, body.top - h * 0.04, w * 0.5, h * 0.06), Pk.fill(const Color(0xFF3B3452)));
  c.drawRect(Rect.fromLTWH(body.center.dx - w * 0.25, body.bottom - h * 0.02, w * 0.5, h * 0.06), Pk.fill(const Color(0xFF3B3452)));
  c.drawLine(Offset(body.center.dx, body.bottom + h * 0.04), Offset(body.center.dx, r.bottom), Pk.stroke(b, 1.2));
}

void _paintSignpost(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  c.drawRect(Rect.fromLTWH(r.center.dx - w * 0.06, r.top + h * 0.05, w * 0.12, h * 0.95), Pk.fill(Pk.dark(a, 0.25)));
  for (final (y, dir, len) in [(0.12, 1.0, 0.5), (0.34, -1.0, 0.48), (0.56, 1.0, 0.4)]) {
    final y0 = r.top + h * y;
    final x0 = r.center.dx;
    final x1 = x0 + dir * w * len;
    Pk.poly(c, [Offset(x0 - dir * w * 0.12, y0), Offset(x1, y0), Offset(x1 + dir * w * 0.1, y0 + h * 0.07), Offset(x1, y0 + h * 0.14), Offset(x0 - dir * w * 0.12, y0 + h * 0.14)], Pk.fill(a));
    c.drawLine(Offset(x0 + dir * w * 0.02, y0 + h * 0.07), Offset(x1 - dir * w * 0.06, y0 + h * 0.07), Pk.stroke(b, 1.4));
  }
  c.drawOval(Rect.fromLTWH(r.center.dx - w * 0.2, r.bottom - h * 0.05, w * 0.4, h * 0.06), Pk.fill(_moss));
}

void _paintBamboo(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  for (var i = 0; i < 4; i++) {
    final x = r.left + w * (0.14 + i * 0.24);
    final top = r.top + h * (0.04 + Pk.rand(i + r.left.toInt()) * 0.16);
    final sway = sin(t * 0.9 + i) * 1.5;
    final stalk = Pk.fill(i.isEven ? a : Pk.dark(a, 0.1));
    c.drawRRect(RRect.fromRectAndRadius(Rect.fromLTRB(x - w * 0.045, top, x + w * 0.045 + sway * 0.2, r.bottom), const Radius.circular(2)), stalk);
    for (var y = top + h * 0.14; y < r.bottom - 4; y += h * 0.16) {
      c.drawLine(Offset(x - w * 0.05, y), Offset(x + w * 0.05, y), Pk.stroke(Pk.dark(a, 0.3), 1.4));
    }
    for (var k = 0; k < 3; k++) {
      final ly = top + h * (0.1 + k * 0.22);
      final d = (k + i).isEven ? 1.0 : -1.0;
      c.save();
      c.translate(x, ly);
      c.rotate(d * 0.9 + sway * 0.05);
      c.drawOval(Rect.fromLTWH(0, -w * 0.035, w * 0.26, w * 0.07), Pk.fill(b));
      c.restore();
    }
  }
}

void _paintStream(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  final p = Path()
    ..moveTo(r.left, r.bottom)
    ..quadraticBezierTo(r.left + w * 0.35, r.top + h * 0.7, r.left + w * 0.55, r.top + h * 0.35)
    ..quadraticBezierTo(r.left + w * 0.72, r.top, r.right, r.top + h * 0.05)
    ..lineTo(r.right, r.top + h * 0.38)
    ..quadraticBezierTo(r.left + w * 0.82, r.top + h * 0.35, r.left + w * 0.72, r.top + h * 0.6)
    ..quadraticBezierTo(r.left + w * 0.55, r.bottom, r.left + w * 0.3, r.bottom)
    ..close();
  c.drawPath(p, Pk.fill(Pk.dark(a, 0.15)));
  c.save();
  c.clipPath(p);
  c.drawRect(r, _vgrad(r, Pk.light(a, 0.2), a));
  for (var i = 0; i < 6; i++) {
    final k = ((t * 0.15 + i / 6) % 1);
    final pt = Offset(r.left + w * (1 - k) * 0.9 + w * 0.05, r.top + h * (0.15 + k * 0.75));
    c.drawLine(pt, pt + Offset(w * 0.08, -h * 0.04), Pk.stroke(Colors.white.withValues(alpha: 0.7), 1.5));
  }
  c.restore();
  for (var i = 0; i < 5; i++) {
    c.drawOval(Rect.fromCenter(center: Offset(r.left + w * (0.12 + i * 0.2), r.top + h * (0.9 - i * 0.18)), width: w * 0.07, height: h * 0.12), Pk.fill(b));
  }
}

void _paintRocks(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  for (final (x, y, rw, rh) in [(0.0, 0.35, 0.55, 0.65), (0.42, 0.0, 0.58, 1.0), (0.22, 0.55, 0.4, 0.45)]) {
    final rr = Rect.fromLTWH(r.left + w * x, r.top + h * y, w * rw, h * rh);
    c.drawRRect(RRect.fromRectAndCorners(rr, topLeft: Radius.circular(rr.width * 0.45), topRight: Radius.circular(rr.width * 0.35), bottomLeft: const Radius.circular(3), bottomRight: const Radius.circular(3)), Pk.fill(a));
    c.drawOval(Rect.fromLTWH(rr.left + rr.width * 0.2, rr.top + rr.height * 0.12, rr.width * 0.3, rr.height * 0.18), Pk.fill(Colors.white.withValues(alpha: 0.25)));
    c.drawOval(Rect.fromLTWH(rr.left + rr.width * 0.45, rr.top, rr.width * 0.4, rr.height * 0.16), Pk.fill(b));
  }
}

void _paintOnsenPool(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  c.drawOval(r, Pk.fill(_darkStone));
  final water = r.deflate(min(w, h) * 0.12);
  c.drawOval(water, _vgrad(water, Pk.dark(a, 0.15), Pk.light(a, 0.2)));
  c.drawOval(Rect.fromCenter(center: water.center + Offset(-w * 0.12, -h * 0.05), width: water.width * 0.35, height: water.height * 0.25), Pk.fill(Colors.white.withValues(alpha: 0.25)));
  final n = max(8, (w / 14).round());
  for (var i = 0; i < n; i++) {
    final ang = i * 2 * pi / n;
    final p = r.center + Offset(cos(ang) * w * 0.47, sin(ang) * h * 0.44);
    final s = min(w, h) * (0.13 + Pk.rand(i + r.left.toInt()) * 0.06);
    c.drawOval(Rect.fromCenter(center: p, width: s * 1.5, height: s), Pk.fill(i.isEven ? b : Pk.light(b, 0.12)));
  }
  for (var i = 0; i < 4; i++) {
    final k = (t * 0.25 + i / 4) % 1;
    final p = Offset(r.left + w * (0.25 + i * 0.17) + sin(t + i) * 4, r.center.dy - k * h * 1.4);
    c.drawCircle(p, w * 0.05 + k * w * 0.06, Pk.fill(Colors.white.withValues(alpha: 0.45 * (1 - k))));
  }
}

void _paintSteam(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  for (var i = 0; i < 6; i++) {
    final k = (t * 0.2 + i / 6) % 1;
    final p = Offset(r.left + w * (0.2 + (i % 3) * 0.3) + sin(t * 0.8 + i) * w * 0.08, r.bottom - k * h);
    c.drawCircle(p, w * (0.12 + k * 0.14), Pk.fill(a.withValues(alpha: 0.5 * (1 - k))));
  }
}

void _paintBucket(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  Pk.poly(c, [Offset(r.left + w * 0.05, r.top + h * 0.3), Offset(r.right - w * 0.05, r.top + h * 0.3), Offset(r.right - w * 0.16, r.bottom), Offset(r.left + w * 0.16, r.bottom)], Pk.fill(a));
  for (var i = 1; i < 5; i++) {
    final x = r.left + w * (0.05 + i * 0.18);
    c.drawLine(Offset(x, r.top + h * 0.32), Offset(x + (i - 2.5) * w * -0.02, r.bottom - 1), Pk.stroke(Pk.dark(a, 0.18), 0.8));
  }
  for (final y in [0.42, 0.82]) {
    c.drawLine(Offset(r.left + w * (0.08 + y * 0.08), r.top + h * y), Offset(r.right - w * (0.08 + y * 0.08), r.top + h * y), Pk.stroke(b, 2));
  }
  c.drawOval(Rect.fromLTWH(r.left + w * 0.05, r.top + h * 0.24, w * 0.9, h * 0.14), Pk.fill(Pk.dark(a, 0.3)));
  c.drawOval(Rect.fromLTWH(r.left + w * 0.12, r.top + h * 0.27, w * 0.76, h * 0.08), Pk.fill(_aqua));
  c.drawLine(Offset(r.left + w * 0.6, r.top + h * 0.3), Offset(r.right + w * 0.05, r.top), Pk.stroke(Pk.dark(a, 0.2), 2));
}

void _paintTieredBench(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  Pk.box(c, Rect.fromLTWH(r.left, r.top, w, h * 0.5), Pk.dark(a, 0.1), radius: 2);
  Pk.box(c, Rect.fromLTWH(r.left - w * 0.03, r.top - h * 0.04, w * 1.06, h * 0.12), a, radius: 2);
  Pk.box(c, Rect.fromLTWH(r.left + w * 0.04, r.top + h * 0.5, w * 0.92, h * 0.5), Pk.dark(a, 0.04), radius: 2);
  Pk.box(c, Rect.fromLTWH(r.left, r.top + h * 0.46, w, h * 0.12), Pk.light(a, 0.08), radius: 2);
  for (var i = 1; i < 6; i++) {
    final x = r.left + w * i / 6;
    c.drawLine(Offset(x, r.top + h * 0.1), Offset(x, r.top + h * 0.46), Pk.stroke(Pk.dark(a, 0.25), 1));
    c.drawLine(Offset(x, r.top + h * 0.58), Offset(x, r.bottom - 2), Pk.stroke(Pk.dark(a, 0.25), 1));
  }
  Pk.box(c, Rect.fromLTWH(r.left + w * 0.12, r.top - h * 0.12, w * 0.22, h * 0.1), b, radius: 3);
}

void _paintSaunaStove(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  Pk.box(c, Rect.fromLTWH(r.left, r.top + h * 0.3, w, h * 0.7), a, radius: 3);
  final door = Rect.fromLTWH(r.left + w * 0.25, r.top + h * 0.52, w * 0.5, h * 0.3);
  c.drawRRect(RRect.fromRectAndRadius(door, const Radius.circular(3)), Pk.fill(const Color(0xFF2A221D)));
  Pk.glow(c, door.center, w * 0.5, _orange, 0.5 + 0.15 * sin(t * 6));
  for (var i = 0; i < 3; i++) {
    final fh = door.height * (0.5 + 0.2 * sin(t * 7 + i * 2));
    Pk.poly(c, [Offset(door.left + door.width * (0.15 + i * 0.3), door.bottom), Offset(door.left + door.width * (0.3 + i * 0.3), door.bottom - fh), Offset(door.left + door.width * (0.45 + i * 0.3), door.bottom)], Pk.fill(i == 1 ? _gold : _orange));
  }
  c.drawRect(Rect.fromLTWH(r.left - w * 0.06, r.top + h * 0.26, w * 1.12, h * 0.06), Pk.fill(Pk.dark(a, 0.3)));
  for (var i = 0; i < 7; i++) {
    final p = Offset(r.left + w * (0.1 + (i % 4) * 0.27), r.top + h * (i < 4 ? 0.22 : 0.12));
    c.drawOval(Rect.fromCenter(center: p, width: w * 0.24, height: h * 0.13), Pk.fill(i.isEven ? b : Pk.dark(b, 0.15)));
  }
  for (var i = 0; i < 3; i++) {
    final k = (t * 0.3 + i / 3) % 1;
    c.drawCircle(Offset(r.left + w * (0.3 + i * 0.2) + sin(t + i) * 3, r.top + h * 0.1 - k * h * 0.5), w * 0.06 + k * w * 0.08, Pk.fill(Colors.white.withValues(alpha: 0.4 * (1 - k))));
  }
}

void _paintHerbBundle(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  c.drawLine(r.topCenter, Offset(r.center.dx, r.top + h * 0.2), Pk.stroke(_darkWood, 1));
  c.drawRect(Rect.fromLTWH(r.center.dx - w * 0.12, r.top + h * 0.18, w * 0.24, h * 0.14), Pk.fill(b));
  for (var i = -3; i <= 3; i++) {
    c.save();
    c.translate(r.center.dx, r.top + h * 0.3);
    c.rotate(i * 0.12 + sin(t + r.left) * 0.03);
    c.drawOval(Rect.fromCenter(center: Offset(0, h * 0.35), width: w * 0.3, height: h * 0.62), Pk.fill(i.isEven ? a : Pk.dark(a, 0.15)));
    c.restore();
  }
}

void _paintLogPile(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  const rows = [3, 2, 1];
  for (var row = 0; row < 3; row++) {
    final n = rows[row];
    final rad = min(w / 6, h / 6);
    for (var i = 0; i < n; i++) {
      final cx = r.center.dx + (i - (n - 1) / 2) * rad * 2;
      final cy = r.bottom - rad - row * rad * 1.75;
      c.drawCircle(Offset(cx, cy), rad, Pk.fill(Pk.dark(a, 0.2)));
      c.drawCircle(Offset(cx, cy), rad * 0.82, Pk.fill(b));
      c.drawCircle(Offset(cx, cy), rad * 0.45, Pk.stroke(Pk.dark(b, 0.2), 1));
    }
  }
}

void _paintTeaSet(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  c.drawOval(Rect.fromLTWH(r.left, r.bottom - h * 0.25, w, h * 0.25), Pk.fill(Pk.dark(b, 0.2)));
  c.drawOval(Rect.fromLTWH(r.left + w * 0.04, r.bottom - h * 0.24, w * 0.92, h * 0.18), Pk.fill(b));
  final pot = Rect.fromLTWH(r.left + w * 0.3, r.top + h * 0.22, w * 0.4, h * 0.58);
  c.drawOval(pot, Pk.fill(a));
  c.drawOval(Rect.fromLTWH(pot.left + pot.width * 0.2, pot.top + pot.height * 0.15, pot.width * 0.25, pot.height * 0.25), Pk.fill(Colors.white.withValues(alpha: 0.35)));
  c.drawLine(Offset(pot.right - 2, pot.center.dy), Offset(pot.right + w * 0.1, pot.top + pot.height * 0.15), Pk.stroke(a, w * 0.05));
  c.drawArc(Rect.fromLTWH(pot.left + pot.width * 0.15, r.top, pot.width * 0.7, h * 0.4), pi, pi, false, Pk.stroke(_darkWood, 1.6));
  for (final x in [0.12, 0.8]) {
    final cup = Rect.fromLTWH(r.left + w * x, r.bottom - h * 0.42, w * 0.13, h * 0.24);
    c.drawRRect(RRect.fromRectAndCorners(cup, bottomLeft: Radius.circular(cup.width * 0.4), bottomRight: Radius.circular(cup.width * 0.4)), Pk.fill(Pk.light(a, 0.15)));
    c.drawOval(Rect.fromLTWH(cup.left, cup.top - 1, cup.width, h * 0.06), Pk.fill(_leaf));
  }
  for (var i = 0; i < 2; i++) {
    final k = (t * 0.35 + i / 2) % 1;
    c.drawCircle(Offset(pot.center.dx + w * 0.22 + sin(t * 2 + i) * 2, pot.top - k * h * 0.5), 2 + k * 3, Pk.fill(Colors.white.withValues(alpha: 0.5 * (1 - k))));
  }
}

void _paintLowTable(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  for (final x in [-0.08, 0.86]) {
    Pk.box(c, Rect.fromLTWH(r.left + w * x, r.top + h * 0.55, w * 0.22, h * 0.45), b, radius: 4);
  }
  c.drawRect(Rect.fromLTWH(r.left + w * 0.22, r.top + h * 0.5, w * 0.06, h * 0.5), Pk.fill(Pk.dark(a, 0.3)));
  c.drawRect(Rect.fromLTWH(r.right - w * 0.28, r.top + h * 0.5, w * 0.06, h * 0.5), Pk.fill(Pk.dark(a, 0.3)));
  Pk.box(c, Rect.fromLTWH(r.left + w * 0.12, r.top + h * 0.36, w * 0.76, h * 0.16), a, radius: 3);
  for (final x in [0.3, 0.58]) {
    final bowl = Rect.fromLTWH(r.left + w * x, r.top + h * 0.1, w * 0.14, h * 0.26);
    c.drawArc(bowl, 0, pi, true, Pk.fill(_red));
    c.drawOval(Rect.fromLTWH(bowl.left, bowl.center.dy - h * 0.04, bowl.width, h * 0.08), Pk.fill(_cream));
  }
  c.drawLine(Offset(r.left + w * 0.5, r.top + h * 0.2), Offset(r.left + w * 0.54, r.top - h * 0.1), Pk.stroke(_darkWood, 1.2));
}

void _paintArchBridge(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  final deck = Path()
    ..moveTo(r.left, r.bottom)
    ..quadraticBezierTo(r.center.dx, r.top + h * 0.05, r.right, r.bottom)
    ..lineTo(r.right - w * 0.06, r.bottom)
    ..quadraticBezierTo(r.center.dx, r.top + h * 0.3, r.left + w * 0.06, r.bottom)
    ..close();
  c.drawPath(deck, Pk.fill(a));
  final rail = Path()
    ..moveTo(r.left + w * 0.04, r.bottom - h * 0.35)
    ..quadraticBezierTo(r.center.dx, r.top - h * 0.3, r.right - w * 0.04, r.bottom - h * 0.35);
  c.drawPath(rail, Pk.stroke(a, 3));
  for (var i = 0; i <= 8; i++) {
    final k = 0.06 + i * 0.11;
    final x = r.left + w * k;
    final yDeck = r.bottom - (r.bottom - (r.top + h * 0.05)) * 4 * k * (1 - k) * 0.5 * 2 * 0.5;
    final yRail = (r.bottom - h * 0.35) - ((r.bottom - h * 0.35) - (r.top - h * 0.3)) * 4 * k * (1 - k) * 0.5;
    c.drawLine(Offset(x, yDeck - 2), Offset(x, yRail), Pk.stroke(i.isEven ? a : Pk.dark(a, 0.15), 2));
    if (i == 0 || i == 8) c.drawCircle(Offset(x, yRail - 2), 2.5, Pk.fill(b));
  }
}

void _paintKoiPond(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  c.drawOval(r, Pk.fill(Pk.dark(_stone, 0.1)));
  final water = r.deflate(min(w, h) * 0.1);
  c.drawOval(water, _vgrad(water, Pk.dark(a, 0.2), Pk.light(a, 0.15)));
  c.save();
  c.clipPath(Path()..addOval(water));
  for (var i = 0; i < 3; i++) {
    final ang = t * 0.4 + i * 2.1;
    final p = water.center + Offset(cos(ang) * water.width * 0.32, sin(ang) * water.height * 0.3);
    c.save();
    c.translate(p.dx, p.dy);
    c.rotate(ang + pi / 2);
    c.drawOval(Rect.fromCenter(center: Offset.zero, width: w * 0.08, height: h * 0.14), Pk.fill(i == 1 ? Colors.white : b));
    c.drawCircle(Offset(0, -h * 0.02), w * 0.015, Pk.fill(i == 1 ? b : Colors.white));
    Pk.poly(c, [Offset(0, h * 0.06), Offset(-w * 0.025, h * 0.1), Offset(w * 0.025, h * 0.1)], Pk.fill(i == 1 ? b : Pk.light(b, 0.2)));
    c.restore();
  }
  c.restore();
  for (final (x, y) in [(0.2, 0.35), (0.72, 0.62)]) {
    final pad = Rect.fromCenter(center: Offset(r.left + w * x, r.top + h * y), width: w * 0.12, height: h * 0.16);
    c.drawArc(pad, 0.4, 2 * pi - 0.8, true, Pk.fill(_leaf));
  }
  Pk.flower(c, Offset(r.left + w * 0.2, r.top + h * 0.33), 0.8, _blossom);
}

void _paintBonsai(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  Pk.box(c, Rect.fromLTWH(r.left + w * 0.12, r.bottom - h * 0.22, w * 0.76, h * 0.22), b, radius: 2);
  c.drawRect(Rect.fromLTWH(r.left + w * 0.05, r.bottom - h * 0.25, w * 0.9, h * 0.05), Pk.fill(Pk.dark(b, 0.2)));
  final trunk = Path()
    ..moveTo(r.center.dx - w * 0.05, r.bottom - h * 0.24)
    ..quadraticBezierTo(r.left + w * 0.2, r.top + h * 0.5, r.center.dx + w * 0.05, r.top + h * 0.35)
    ..quadraticBezierTo(r.right - w * 0.2, r.top + h * 0.25, r.right - w * 0.25, r.top + h * 0.2);
  c.drawPath(trunk, Pk.stroke(const Color(0xFF6E4A30), w * 0.08));
  for (final (x, y, s) in [(0.3, 0.32, 0.22), (0.62, 0.18, 0.26), (0.78, 0.36, 0.18)]) {
    c.drawOval(Rect.fromCenter(center: Offset(r.left + w * x, r.top + h * y), width: w * s * 2, height: h * s), Pk.fill(a));
    c.drawOval(Rect.fromCenter(center: Offset(r.left + w * x - w * 0.04, r.top + h * y - h * 0.03), width: w * s, height: h * s * 0.4), Pk.fill(Pk.light(a, 0.2)));
  }
}

void _paintSkyLantern(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  final bob = sin(t * 0.8 + r.left * 0.1) * h * 0.08;
  final body = Rect.fromLTWH(r.left, r.top + bob, w, h * 0.85);
  Pk.glow(c, body.center, w * 1.6, b, 0.45);
  Pk.poly(c, [Offset(body.left, body.top), Offset(body.right, body.top), Offset(body.right - w * 0.15, body.bottom), Offset(body.left + w * 0.15, body.bottom)], Pk.fill(a));
  c.drawRect(Rect.fromLTWH(body.left + w * 0.3, body.top + h * 0.1, w * 0.4, h * 0.6), Pk.fill(Colors.white.withValues(alpha: 0.4)));
  c.drawCircle(Offset(body.center.dx, body.bottom - h * 0.05), w * 0.12, Pk.fill(b));
}

