void _mountainPath(Canvas c, double ov, double t) {
  final far = Pk.mix(const Color(0xFFA8AAA0), const Color(0xFF9FB8D8), ov);
  final mid = Pk.mix(const Color(0xFF9A9C8C), const Color(0xFF6FA86A), ov);
  Pk.poly(c, const [Offset(-20, 140), Offset(70, 46), Offset(150, 110), Offset(230, 30), Offset(330, 104), Offset(420, 56), Offset(420, 140)], Pk.fill(far));
  for (final p in const [Offset(70, 46), Offset(230, 30), Offset(420, 56)]) {
    Pk.poly(c, [p + const Offset(-18, 18), p, p + const Offset(18, 18)], Pk.fill(Colors.white.withValues(alpha: 0.85)));
  }
  final hills = Path()
    ..moveTo(0, 124)
    ..quadraticBezierTo(100, 96, 200, 118)
    ..quadraticBezierTo(300, 92, 400, 116)
    ..lineTo(400, 142)
    ..lineTo(0, 142)
    ..close();
  c.drawPath(hills, Pk.fill(mid));
  final roof = Pk.mix(const Color(0xFF6E6A70), const Color(0xFF8A3A2E), ov);
  c.drawRect(const Rect.fromLTWH(186, 92, 28, 20), Pk.fill(Pk.mix(const Color(0xFFB5A99A), const Color(0xFFFFF1DA), ov)));
  Pk.poly(c, const [Offset(176, 94), Offset(200, 80), Offset(224, 94)], Pk.fill(roof));
  for (var i = 0; i < 3; i++) {
    final k = (t * 0.15 + i / 3) % 1;
    c.drawCircle(Offset(200 + sin(t + i) * 6, 80 - k * 40), 4 + k * 8, Pk.fill(Colors.white.withValues(alpha: 0.4 * (1 - k) * ov)));
  }
}

void _onsenYard(Canvas c, double ov, double t) {
  final far = Pk.mix(const Color(0xFFA8AAA0), const Color(0xFF8FB0D0), ov);
  Pk.poly(c, const [Offset(-20, 130), Offset(90, 40), Offset(190, 120), Offset(300, 34), Offset(420, 130)], Pk.fill(far));
  Pk.poly(c, const [Offset(72, 56), Offset(90, 40), Offset(108, 56)], Pk.fill(Colors.white));
  Pk.poly(c, const [Offset(280, 52), Offset(300, 34), Offset(320, 52)], Pk.fill(Colors.white));
  final bamboo = Pk.mix(const Color(0xFFA8A27E), const Color(0xFFC9B26A), ov);
  for (var i = 0; i < 40; i++) {
    final x = i * 10.0;
    c.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(x + 1, 78 + (i % 3) * 2.0, 8, 54), const Radius.circular(3)), Pk.fill(i.isEven ? bamboo : Pk.dark(bamboo, 0.08)));
  }
  c.drawRect(const Rect.fromLTWH(0, 94, 400, 3), Pk.fill(Pk.dark(bamboo, 0.35)));
  c.drawRect(const Rect.fromLTWH(0, 116, 400, 3), Pk.fill(Pk.dark(bamboo, 0.35)));
}

void _cedarRoom(Canvas c, double ov, double t) {
  final wood = Pk.mix(const Color(0xFF9A8C7A), const Color(0xFFD9A066), ov);
  c.drawRect(const Rect.fromLTWH(0, 0, 400, 172), Pk.fill(Pk.alpha(wood, 0.55)));
  for (var i = 0; i < 25; i++) {
    c.drawLine(Offset(i * 16.0, 0), Offset(i * 16.0, 172), Pk.stroke(Pk.dark(wood, 0.25), 1));
  }
  final win = const Rect.fromLTWH(176, 28, 48, 34);
  Pk.box(c, win.inflate(3), Pk.dark(wood, 0.3), radius: 2);
  c.drawRect(win, _vgrad(win, Pk.mix(const Color(0xFFB0B8C0), const Color(0xFFBFE6FF), ov), Pk.mix(const Color(0xFFC8C8C0), const Color(0xFFE6F6FF), ov)));
  c.drawLine(win.topCenter, win.bottomCenter, Pk.stroke(Pk.dark(wood, 0.3), 2));
}

void _teaGardenBack(Canvas c, double ov, double t) {
  final hill = Pk.mix(const Color(0xFFA7AE8C), const Color(0xFF8ED46A), ov);
  final house = Pk.mix(const Color(0xFFB5A99A), const Color(0xFFFFF4E0), ov);
  final roof = Pk.mix(const Color(0xFF6E6A70), const Color(0xFF4A5A6E), ov);
  c.drawRect(const Rect.fromLTWH(150, 84, 90, 52), Pk.fill(house));
  for (var i = 0; i < 4; i++) {
    c.drawLine(Offset(150 + i * 22.5, 84), Offset(150 + i * 22.5, 136), Pk.stroke(Pk.dark(house, 0.3), 1.5));
  }
  c.drawLine(const Offset(150, 108), const Offset(240, 108), Pk.stroke(Pk.dark(house, 0.3), 1.5));
  final r1 = Path()
    ..moveTo(132, 90)
    ..quadraticBezierTo(150, 82, 160, 68)
    ..lineTo(230, 68)
    ..quadraticBezierTo(240, 82, 258, 90)
    ..close();
  c.drawPath(r1, Pk.fill(roof));
  final hills = Path()
    ..moveTo(0, 132)
    ..quadraticBezierTo(70, 112, 140, 130)
    ..lineTo(140, 142)
    ..lineTo(0, 142)
    ..close();
  c.drawPath(hills, Pk.fill(hill));
  final hills2 = Path()
    ..moveTo(250, 130)
    ..quadraticBezierTo(330, 108, 400, 126)
    ..lineTo(400, 142)
    ..lineTo(250, 142)
    ..close();
  c.drawPath(hills2, Pk.fill(hill));
  for (var i = 0; i < 10; i++) {
    final k = (t * 0.06 + Pk.rand(i)) % 1;
    final p = Offset((Pk.rand(i + 4) * 400 + t * 8) % 400, k * 240);
    c.drawOval(Rect.fromCenter(center: p, width: 4, height: 2.5), Pk.fill(_blossom.withValues(alpha: 0.85 * ov)));
  }
}

void _terraceNight(Canvas c, double ov, double t) {
  final far = Pk.mix(const Color(0xFF4A4E66), const Color(0xFF3A3E78), ov);
  final near = Pk.mix(const Color(0xFF5A5A6A), const Color(0xFF2E4A5E), ov);
  Pk.poly(c, const [Offset(-20, 150), Offset(80, 70), Offset(170, 130), Offset(270, 60), Offset(420, 150)], Pk.fill(far));
  final valley = Path()
    ..moveTo(0, 130)
    ..quadraticBezierTo(140, 108, 240, 132)
    ..quadraticBezierTo(330, 116, 400, 128)
    ..lineTo(400, 152)
    ..lineTo(0, 152)
    ..close();
  c.drawPath(valley, Pk.fill(near));
  for (var i = 0; i < 14; i++) {
    c.drawCircle(Offset(20 + Pk.rand(i + 60) * 360, 132 + Pk.rand(i + 70) * 14), 1.2, Pk.fill(_lampGlow.withValues(alpha: 0.7 * ov)));
  }
  final beam = Pk.mix(const Color(0xFF5A4E46), const Color(0xFF6E3A28), ov);
  c.drawRect(const Rect.fromLTWH(0, 0, 400, 10), Pk.fill(beam));
  for (final x in [6.0, 388.0]) {
    c.drawRect(Rect.fromLTWH(x, 0, 8, 152), Pk.fill(beam));
  }
  final rail = Pk.mix(const Color(0xFF6E625A), const Color(0xFF8A4A30), ov);
  c.drawRect(const Rect.fromLTWH(0, 132, 400, 4), Pk.fill(rail));
  for (var i = 0; i < 26; i++) {
    c.drawRect(Rect.fromLTWH(i * 16.0, 132, 3, 20), Pk.fill(rail));
  }
}

