void _paintRocket(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  final g = Pk.stroke(_darkSteel, 1.6);
  final tower = Rect.fromLTWH(r.right - w * 0.2, r.top + h * 0.12, w * 0.16, h * 0.8);
  c.drawLine(tower.topLeft, tower.bottomLeft, g);
  c.drawLine(tower.topRight, tower.bottomRight, g);
  for (var y = tower.top; y < tower.bottom; y += tower.width) {
    c.drawLine(Offset(tower.left, y), Offset(tower.right, y + tower.width), g);
    c.drawLine(Offset(tower.right, y), Offset(tower.left, y + tower.width), g);
  }
  c.drawLine(Offset(tower.left, r.top + h * 0.35), Offset(r.left + w * 0.55, r.top + h * 0.35), Pk.stroke(_darkSteel, 2.5));
  final cx = r.left + w * 0.38;
  final bw = w * 0.32;
  final body = Rect.fromLTWH(cx - bw / 2, r.top + h * 0.22, bw, h * 0.6);
  for (final d in [-1.0, 1.0]) {
    Pk.poly(c, [Offset(cx + d * bw * 0.45, body.bottom - h * 0.2), Offset(cx + d * bw * 1.05, body.bottom + h * 0.02), Offset(cx + d * bw * 0.45, body.bottom)], Pk.fill(b));
  }
  c.drawRRect(RRect.fromRectAndRadius(body, Radius.circular(bw * 0.3)), Pk.fill(a));
  c.drawRect(Rect.fromLTWH(body.left + bw * 0.15, body.top + 4, bw * 0.12, body.height - 8), Pk.fill(Colors.white.withValues(alpha: 0.4)));
  final nose = Path()
    ..moveTo(body.left, body.top + h * 0.04)
    ..quadraticBezierTo(body.left, r.top + h * 0.05, cx, r.top)
    ..quadraticBezierTo(body.right, r.top + h * 0.05, body.right, body.top + h * 0.04)
    ..close();
  c.drawPath(nose, Pk.fill(b));
  for (final y in [0.36, 0.5]) {
    c.drawCircle(Offset(cx, r.top + h * y), bw * 0.2, Pk.fill(_darkSteel));
    c.drawCircle(Offset(cx, r.top + h * y), bw * 0.14, Pk.fill(_cyan));
  }
  c.drawRect(Rect.fromLTWH(body.left, r.top + h * 0.62, bw, h * 0.04), Pk.fill(b));
  Pk.poly(c, [Offset(cx - bw * 0.28, body.bottom), Offset(cx + bw * 0.28, body.bottom), Offset(cx + bw * 0.36, body.bottom + h * 0.06), Offset(cx - bw * 0.36, body.bottom + h * 0.06)], Pk.fill(_darkSteel));
  final f = 0.6 + 0.4 * sin(t * 9);
  Pk.glow(c, Offset(cx, body.bottom + h * 0.08), bw * 0.9, _orange, 0.35 * f);
  Pk.box(c, Rect.fromLTWH(r.left, r.bottom - h * 0.08, w, h * 0.08), _steel, radius: 2);
}

void _paintRadarDish(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  Pk.box(c, Rect.fromLTWH(r.left + w * 0.3, r.bottom - h * 0.12, w * 0.4, h * 0.12), _darkSteel, radius: 2);
  c.drawRect(Rect.fromLTWH(r.center.dx - w * 0.05, r.top + h * 0.5, w * 0.1, h * 0.4), Pk.fill(_darkSteel));
  final swing = sin(t * 0.5) * 0.25;
  c.save();
  c.translate(r.center.dx, r.top + h * 0.5);
  c.rotate(-0.5 + swing);
  final dish = Rect.fromCenter(center: Offset(0, -h * 0.12), width: w * 0.95, height: h * 0.6);
  c.drawArc(dish, 0, pi, true, Pk.fill(a));
  c.drawArc(dish.deflate(w * 0.06), 0, pi, true, Pk.fill(Pk.light(a, 0.2)));
  c.drawLine(Offset(0, -h * 0.12), Offset(0, -h * 0.5), Pk.stroke(_darkSteel, 1.6));
  c.drawCircle(Offset(0, -h * 0.5), w * 0.05, Pk.fill(b));
  c.restore();
  Pk.glow(c, Offset(r.center.dx, r.top + h * 0.15), w * 0.3, b, 0.3 + 0.3 * sin(t * 3));
}

void _paintSolarPanel(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  c.drawRect(Rect.fromLTWH(r.center.dx - w * 0.03, r.top + h * 0.5, w * 0.06, h * 0.5), Pk.fill(_darkSteel));
  final panel = [Offset(r.left + w * 0.08, r.top), Offset(r.right, r.top + h * 0.1), Offset(r.right - w * 0.08, r.top + h * 0.6), Offset(r.left, r.top + h * 0.5)];
  Pk.poly(c, panel, Pk.fill(_steel));
  final inner = [for (final p in panel) Offset.lerp(p, Offset(r.center.dx, r.top + h * 0.3), 0.08)!];
  Pk.poly(c, inner, Pk.fill(a));
  for (var i = 1; i < 5; i++) {
    final k = i / 5;
    c.drawLine(Offset.lerp(inner[0], inner[1], k)!, Offset.lerp(inner[3], inner[2], k)!, Pk.stroke(Pk.light(a, 0.3), 0.8));
  }
  c.drawLine(Offset.lerp(inner[0], inner[3], 0.5)!, Offset.lerp(inner[1], inner[2], 0.5)!, Pk.stroke(Pk.light(a, 0.3), 0.8));
  final k = (t * 0.3) % 1;
  c.drawLine(Offset.lerp(inner[0], inner[1], k)!, Offset.lerp(inner[3], inner[2], k)!, Pk.stroke(b.withValues(alpha: 0.6), 2));
}

void _paintAntenna(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  final g = Pk.stroke(a, 1.4);
  final top = Offset(r.center.dx, r.top + h * 0.1);
  c.drawLine(top, Offset(r.left, r.bottom), g);
  c.drawLine(top, Offset(r.right, r.bottom), g);
  for (var i = 1; i < 6; i++) {
    final k = i / 6;
    final y = top.dy + (r.bottom - top.dy) * k;
    final half = w * 0.5 * k;
    c.drawLine(Offset(r.center.dx - half, y), Offset(r.center.dx + half, y), g);
    if (i < 5) c.drawLine(Offset(r.center.dx - half, y), Offset(r.center.dx + w * 0.5 * (i + 1) / 6, top.dy + (r.bottom - top.dy) * (i + 1) / 6), g);
  }
  c.drawLine(top, Offset(r.center.dx, r.top), Pk.stroke(a, 1.2));
  for (final y in [0.25, 0.4]) {
    c.drawLine(Offset(r.center.dx - w * 0.35, r.top + h * y), Offset(r.center.dx + w * 0.35, r.top + h * y), Pk.stroke(a, 1.2));
  }
  final on = sin(t * 4 + r.left) > 0;
  Pk.glow(c, Offset(r.center.dx, r.top + 1), 9, b, on ? 0.8 : 0.2);
  c.drawCircle(Offset(r.center.dx, r.top + 1), 2, Pk.fill(on ? b : Pk.dark(b, 0.4)));
}

void _paintCargoPod(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  Pk.box(c, Rect.fromLTWH(r.left, r.top + h * 0.1, w, h * 0.9), a, radius: h * 0.3);
  for (final x in [0.25, 0.75]) {
    c.drawRect(Rect.fromLTWH(r.left + w * x - w * 0.04, r.top + h * 0.1, w * 0.08, h * 0.9), Pk.fill(b));
  }
  c.drawCircle(Offset(r.center.dx, r.top + h * 0.5), min(w, h) * 0.14, Pk.fill(Pk.dark(a, 0.3)));
  c.drawCircle(Offset(r.center.dx, r.top + h * 0.5), min(w, h) * 0.07, Pk.fill(_cyan));
}

void _paintRover(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  Pk.box(c, Rect.fromLTWH(r.left + w * 0.08, r.top + h * 0.3, w * 0.84, h * 0.32), a, radius: 4);
  Pk.box(c, Rect.fromLTWH(r.left + w * 0.2, r.top + h * 0.1, w * 0.4, h * 0.24), _steel, radius: 3);
  c.drawRect(Rect.fromLTWH(r.left + w * 0.25, r.top + h * 0.14, w * 0.3, h * 0.12), Pk.fill(_cyan));
  c.drawLine(Offset(r.right - w * 0.2, r.top + h * 0.3), Offset(r.right - w * 0.15, r.top - h * 0.1), Pk.stroke(_darkSteel, 1.4));
  c.drawCircle(Offset(r.right - w * 0.15, r.top - h * 0.1), 2.5, Pk.fill(b));
  for (final x in [0.2, 0.5, 0.8]) {
    c.drawCircle(Offset(r.left + w * x, r.bottom - h * 0.18), h * 0.18, Pk.fill(const Color(0xFF2A2440)));
    c.drawCircle(Offset(r.left + w * x, r.bottom - h * 0.18), h * 0.07, Pk.fill(_steel));
  }
}

void _paintControlDesk(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  Pk.box(c, Rect.fromLTWH(r.left, r.top + h * 0.4, w, h * 0.6), a, radius: 3);
  Pk.poly(c, [Offset(r.left - 2, r.top + h * 0.42), Offset(r.left + w * 0.06, r.top + h * 0.1), Offset(r.right - w * 0.06, r.top + h * 0.1), Offset(r.right + 2, r.top + h * 0.42)], Pk.fill(Pk.dark(a, 0.25)));
  final n = max(3, (w / 26).round());
  for (var i = 0; i < n; i++) {
    final sx = r.left + w * (0.08 + i * 0.84 / n);
    final scr = Rect.fromLTWH(sx, r.top + h * 0.15, w * 0.84 / n - 4, h * 0.18);
    c.drawRect(scr, Pk.fill(const Color(0xFF14111F)));
    c.drawRect(scr.deflate(1.5), Pk.fill(Pk.alpha(i.isEven ? b : _mint, 0.85)));
    c.drawLine(scr.centerLeft + const Offset(3, 0), scr.centerLeft + Offset(scr.width * (0.3 + 0.5 * ((sin(t * 2 + i) + 1) / 2)), 0), Pk.stroke(Colors.white, 1));
  }
  for (var i = 0; i < 9; i++) {
    final on = sin(t * 3 + i * 1.7) > 0.2;
    final col = [_ruby, _gold, _emerald][i % 3];
    c.drawCircle(Offset(r.left + w * (0.1 + i * 0.1), r.top + h * 0.38), 1.8, Pk.fill(on ? col : Pk.dark(col, 0.5)));
  }
}

void _paintStarMap(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  Pk.box(c, r.inflate(3), a, radius: 3);
  c.drawRect(r, _vgrad(r, const Color(0xFF14183A), const Color(0xFF2A1E5A)));
  final pts = [for (var i = 0; i < 7; i++) Offset(r.left + w * (0.1 + Pk.rand(i * 5 + 1) * 0.8), r.top + h * (0.15 + Pk.rand(i * 5 + 3) * 0.7))];
  for (var i = 0; i < pts.length - 1; i++) {
    c.drawLine(pts[i], pts[i + 1], Pk.stroke(b.withValues(alpha: 0.6), 0.8));
  }
  for (final p in pts) {
    c.drawCircle(p, 1.6, Pk.fill(Colors.white));
  }
  for (var i = 0; i < 14; i++) {
    c.drawCircle(Offset(r.left + w * Pk.rand(i + 40), r.top + h * Pk.rand(i + 60)), 0.7, Pk.fill(Colors.white.withValues(alpha: 0.6)));
  }
  c.drawCircle(Offset(r.left + w * 0.78, r.top + h * 0.3), h * 0.12, Pk.fill(_orange));
  c.drawOval(Rect.fromCenter(center: Offset(r.left + w * 0.78, r.top + h * 0.3), width: h * 0.4, height: h * 0.08), Pk.stroke(_paper, 1));
}

void _paintRadarScope(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  final cc = r.center;
  final rad = min(w, h) / 2;
  c.drawCircle(cc, rad + 3, Pk.fill(a));
  c.drawCircle(cc, rad, Pk.fill(const Color(0xFF0E2A1E)));
  for (final k in [0.33, 0.66, 1.0]) {
    c.drawCircle(cc, rad * k, Pk.stroke(b.withValues(alpha: 0.45), 0.8));
  }
  c.drawLine(cc - Offset(rad, 0), cc + Offset(rad, 0), Pk.stroke(b.withValues(alpha: 0.35), 0.8));
  c.drawLine(cc - Offset(0, rad), cc + Offset(0, rad), Pk.stroke(b.withValues(alpha: 0.35), 0.8));
  final ang = t * 1.5;
  c.drawArc(Rect.fromCircle(center: cc, radius: rad), ang - 0.6, 0.6, true, Pk.fill(b.withValues(alpha: 0.3)));
  c.drawLine(cc, cc + Offset(cos(ang), sin(ang)) * rad, Pk.stroke(b, 1.4));
  for (var i = 0; i < 3; i++) {
    c.drawCircle(cc + Offset(cos(i * 2.3 + 1), sin(i * 2.3 + 1)) * rad * (0.4 + i * 0.18), 1.6, Pk.fill(b));
  }
}

void _paintLaunchButton(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  Pk.poly(c, [Offset(r.left + w * 0.2, r.top + h * 0.35), Offset(r.right - w * 0.2, r.top + h * 0.35), Offset(r.right - w * 0.08, r.bottom), Offset(r.left + w * 0.08, r.bottom)], Pk.fill(_darkSteel));
  for (var i = 0; i < 4; i++) {
    c.drawLine(Offset(r.left + w * (0.15 + i * 0.2), r.top + h * 0.6), Offset(r.left + w * (0.25 + i * 0.2), r.top + h * 0.48), Pk.stroke(i.isEven ? _gold : _ebony, 2.5));
  }
  Pk.box(c, Rect.fromLTWH(r.left + w * 0.05, r.top + h * 0.28, w * 0.9, h * 0.1), _steel, radius: 2);
  final pulse = 0.5 + 0.5 * sin(t * 4);
  Pk.glow(c, Offset(r.center.dx, r.top + h * 0.2), w * 0.8, a, 0.3 + 0.3 * pulse);
  c.drawArc(Rect.fromLTWH(r.left + w * 0.2, r.top + h * 0.06, w * 0.6, h * 0.44), pi, pi, true, Pk.fill(a));
  c.drawOval(Rect.fromLTWH(r.left + w * 0.32, r.top + h * 0.12, w * 0.16, h * 0.06), Pk.fill(Colors.white.withValues(alpha: 0.6)));
  c.drawArc(Rect.fromLTWH(r.left + w * 0.12, r.top - h * 0.02, w * 0.76, h * 0.6), pi, pi, false, Pk.stroke(b.withValues(alpha: 0.7), 1.2));
}

void _paintPlantRack(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  for (final x in [r.left, r.right - w * 0.05]) {
    c.drawRect(Rect.fromLTWH(x, r.top, w * 0.05, h), Pk.fill(a));
  }
  for (var s = 0; s < 3; s++) {
    final y = r.top + h * (0.3 + s * 0.33);
    Pk.glow(c, Offset(r.center.dx, y - h * 0.18), w * 0.4, _purple, 0.2);
    c.drawRect(Rect.fromLTWH(r.left + w * 0.06, y - h * 0.3, w * 0.88, 2), Pk.fill(const Color(0xFFD9B8FF)));
    Pk.box(c, Rect.fromLTWH(r.left, y, w, h * 0.06), Pk.light(a, 0.2), radius: 1);
    for (var i = 0; i < 4; i++) {
      final px = r.left + w * (0.16 + i * 0.22);
      for (var k = -1; k <= 1; k++) {
        c.save();
        c.translate(px, y);
        c.rotate(k * 0.5 + sin(t + i + s) * 0.05);
        c.drawOval(Rect.fromCenter(center: Offset(0, -h * 0.08), width: w * 0.06, height: h * 0.16), Pk.fill(k == 0 ? b : Pk.dark(b, 0.12)));
        c.restore();
      }
      if ((i + s).isEven) c.drawCircle(Offset(px + w * 0.04, y - h * 0.12), w * 0.025, Pk.fill(_red));
    }
  }
}

void _paintGrowLight(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  c.drawLine(Offset(r.left + w * 0.2, r.top), Offset(r.left + w * 0.2, r.top + h * 0.3), Pk.stroke(_darkSteel, 1));
  c.drawLine(Offset(r.right - w * 0.2, r.top), Offset(r.right - w * 0.2, r.top + h * 0.3), Pk.stroke(_darkSteel, 1));
  final cone = Path()
    ..moveTo(r.left + w * 0.05, r.top + h * 0.42)
    ..lineTo(r.right - w * 0.05, r.top + h * 0.42)
    ..lineTo(r.right + w * 0.15, r.bottom)
    ..lineTo(r.left - w * 0.15, r.bottom)
    ..close();
  c.drawPath(cone, _vgrad(Rect.fromLTWH(r.left, r.top + h * 0.42, w, h * 0.58), b.withValues(alpha: 0.35 + 0.05 * sin(t * 2)), b.withValues(alpha: 0)));
  Pk.box(c, Rect.fromLTWH(r.left, r.top + h * 0.3, w, h * 0.14), a, radius: 3);
  c.drawRect(Rect.fromLTWH(r.left + w * 0.06, r.top + h * 0.4, w * 0.88, h * 0.04), Pk.fill(b));
}

void _paintWaterTank(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  final body = Rect.fromLTWH(r.left, r.top + h * 0.08, w, h * 0.84);
  c.drawRRect(RRect.fromRectAndRadius(body, Radius.circular(w * 0.2)), Pk.fill(a));
  final glass = Rect.fromLTWH(body.left + w * 0.3, body.top + h * 0.12, w * 0.24, body.height * 0.7);
  c.drawRRect(RRect.fromRectAndRadius(glass, const Radius.circular(3)), Pk.fill(Pk.dark(a, 0.35)));
  final level = 0.35 + 0.05 * sin(t);
  final water = Rect.fromLTRB(glass.left + 1.5, glass.top + glass.height * level, glass.right - 1.5, glass.bottom - 1.5);
  c.drawRRect(RRect.fromRectAndRadius(water, const Radius.circular(2)), Pk.fill(b));
  c.drawCircle(Offset(water.center.dx, water.bottom - ((t * 12) % water.height)), 1.2, Pk.fill(Colors.white.withValues(alpha: 0.8)));
  for (final y in [0.2, 0.85]) {
    c.drawRect(Rect.fromLTWH(body.left - 1, body.top + body.height * y, w + 2, 3), Pk.fill(Pk.dark(a, 0.2)));
  }
  c.drawRect(Rect.fromLTWH(r.right - 1, r.top + h * 0.3, w * 0.25, 4), Pk.fill(_darkSteel));
  c.drawRect(Rect.fromLTWH(r.left + w * 0.15, r.bottom - h * 0.1, w * 0.12, h * 0.1), Pk.fill(_darkSteel));
  c.drawRect(Rect.fromLTWH(r.right - w * 0.27, r.bottom - h * 0.1, w * 0.12, h * 0.1), Pk.fill(_darkSteel));
}

void _paintSeedPod(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  Pk.box(c, Rect.fromLTWH(r.left, r.bottom - h * 0.25, w, h * 0.25), a, radius: 3);
  final dome = Rect.fromLTWH(r.left + w * 0.08, r.top, w * 0.84, h * 0.9);
  c.drawArc(dome, pi, pi, true, Pk.fill(_cyan.withValues(alpha: 0.25)));
  c.drawArc(Rect.fromLTWH(dome.left, dome.top, dome.width, dome.height * 1.0), pi, pi, false, Pk.stroke(Colors.white.withValues(alpha: 0.8), 1.4));
  final base = Offset(r.center.dx, r.bottom - h * 0.25);
  c.drawLine(base, base - Offset(0, h * 0.35), Pk.stroke(b, 2));
  for (final d in [-1.0, 1.0]) {
    c.save();
    c.translate(base.dx, base.dy - h * 0.3);
    c.rotate(d * 0.8);
    c.drawOval(Rect.fromCenter(center: Offset(0, -h * 0.08), width: w * 0.14, height: h * 0.2), Pk.fill(b));
    c.restore();
  }
  c.drawCircle(Offset(r.right - w * 0.18, r.bottom - h * 0.12), 1.8, Pk.fill(sin(t * 3 + r.left) > 0 ? _emerald : _gold));
}

void _paintBunk(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  for (final x in [r.left, r.right - w * 0.06]) {
    Pk.box(c, Rect.fromLTWH(x, r.top, w * 0.06, h), a, radius: 2);
  }
  for (final y in [0.0, 0.52]) {
    final top = r.top + h * y;
    Pk.box(c, Rect.fromLTWH(r.left + w * 0.06, top + h * 0.3, w * 0.88, h * 0.12), Pk.dark(a, 0.1), radius: 2);
    Pk.box(c, Rect.fromLTWH(r.left + w * 0.07, top + h * 0.2, w * 0.86, h * 0.12), Colors.white, radius: 3);
    Pk.box(c, Rect.fromLTWH(r.left + w * 0.3, top + h * 0.18, w * 0.62, h * 0.14), b, radius: 3);
    Pk.box(c, Rect.fromLTWH(r.left + w * 0.1, top + h * 0.13, w * 0.16, h * 0.1), Colors.white, radius: 3);
  }
  for (var i = 0; i < 5; i++) {
    c.drawLine(Offset(r.right - w * 0.2, r.top + h * (0.45 + i * 0.1)), Offset(r.right - w * 0.08, r.top + h * (0.45 + i * 0.1)), Pk.stroke(Pk.dark(a, 0.2), 1.5));
  }
  c.drawLine(Offset(r.right - w * 0.2, r.top + h * 0.42), Offset(r.right - w * 0.2, r.bottom), Pk.stroke(Pk.dark(a, 0.2), 1.5));
}

void _paintPorthole(Canvas c, Rect r, Color a, Color b, double t) {
  final cc = r.center;
  final rad = min(r.width, r.height) / 2;
  c.drawCircle(cc, rad, Pk.fill(a));
  c.drawCircle(cc, rad * 0.78, Pk.fill(_night));
  c.save();
  c.clipPath(Path()..addOval(Rect.fromCircle(center: cc, radius: rad * 0.78)));
  for (var i = 0; i < 8; i++) {
    c.drawCircle(cc + Offset((Pk.rand(i + r.left.toInt()) - 0.5) * rad * 1.5, (Pk.rand(i + 9) - 0.5) * rad * 1.5), 0.8, Pk.fill(Colors.white));
  }
  c.drawCircle(cc + Offset(rad * 0.3, rad * 0.35), rad * 0.45, Pk.fill(b));
  c.drawCircle(cc + Offset(rad * 0.2, rad * 0.25), rad * 0.15, Pk.fill(_emerald.withValues(alpha: 0.8)));
  c.restore();
  for (var i = 0; i < 8; i++) {
    final ang = i * pi / 4;
    c.drawCircle(cc + Offset(cos(ang), sin(ang)) * rad * 0.89, rad * 0.05, Pk.fill(Pk.dark(a, 0.3)));
  }
  c.drawArc(Rect.fromCircle(center: cc, radius: rad * 0.6), pi * 1.1, 0.7, false, Pk.stroke(Colors.white.withValues(alpha: 0.5), 2));
}

void _paintBigTelescope(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  Pk.box(c, Rect.fromLTWH(r.left + w * 0.25, r.bottom - h * 0.14, w * 0.5, h * 0.14), _darkSteel, radius: 2);
  c.drawRect(Rect.fromLTWH(r.center.dx - w * 0.05, r.top + h * 0.5, w * 0.1, h * 0.38), Pk.fill(_darkSteel));
  c.save();
  c.translate(r.center.dx, r.top + h * 0.5);
  c.rotate(-0.7 + sin(t * 0.3) * 0.05);
  Pk.box(c, Rect.fromLTWH(-w * 0.3, -h * 0.13, w * 0.85, h * 0.26), a, radius: 4);
  c.drawRect(Rect.fromLTWH(w * 0.5, -h * 0.15, w * 0.08, h * 0.3), Pk.fill(b));
  c.drawRect(Rect.fromLTWH(-w * 0.05, -h * 0.15, w * 0.08, h * 0.3), Pk.fill(b));
  c.drawRect(Rect.fromLTWH(-w * 0.4, -h * 0.06, w * 0.1, h * 0.12), Pk.fill(_darkSteel));
  c.restore();
  c.drawCircle(Offset(r.center.dx, r.top + h * 0.5), w * 0.07, Pk.fill(b));
}

void _paintSatellite(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  c.save();
  c.translate(r.center.dx, r.center.dy);
  c.rotate(sin(t * 0.6 + r.left) * 0.12);
  for (final d in [-1.0, 1.0]) {
    final wing = Rect.fromLTWH(d < 0 ? -w * 0.5 : w * 0.17, -h * 0.17, w * 0.33, h * 0.34);
    c.drawRect(wing, Pk.fill(b));
    for (var i = 1; i < 3; i++) {
      c.drawLine(Offset(wing.left + wing.width * i / 3, wing.top), Offset(wing.left + wing.width * i / 3, wing.bottom), Pk.stroke(Pk.light(b, 0.35), 0.8));
    }
    c.drawLine(Offset(d * w * 0.12, 0), Offset(d * w * 0.17, 0), Pk.stroke(_darkSteel, 1.5));
  }
  Pk.box(c, Rect.fromCenter(center: Offset.zero, width: w * 0.26, height: h * 0.5), a, radius: 3);
  c.drawArc(Rect.fromCenter(center: Offset(0, -h * 0.34), width: w * 0.22, height: h * 0.2), 0, pi, true, Pk.fill(_steel));
  c.drawLine(Offset(0, -h * 0.3), Offset(0, -h * 0.48), Pk.stroke(_darkSteel, 1));
  c.restore();
}

void _paintShuttle(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  c.drawRect(Rect.fromLTWH(r.center.dx - w * 0.03, r.top + h * 0.55, w * 0.06, h * 0.35), Pk.fill(_darkSteel));
  Pk.box(c, Rect.fromLTWH(r.left + w * 0.3, r.bottom - h * 0.1, w * 0.4, h * 0.1), _darkSteel, radius: 2);
  final body = Path()
    ..moveTo(r.left + w * 0.05, r.top + h * 0.42)
    ..quadraticBezierTo(r.left + w * 0.1, r.top + h * 0.28, r.left + w * 0.3, r.top + h * 0.26)
    ..lineTo(r.right - w * 0.1, r.top + h * 0.28)
    ..lineTo(r.right, r.top + h * 0.5)
    ..lineTo(r.left + w * 0.12, r.top + h * 0.52)
    ..close();
  Pk.poly(c, [Offset(r.left + w * 0.45, r.top + h * 0.48), Offset(r.right - w * 0.15, r.top + h * 0.48), Offset(r.right - w * 0.02, r.top + h * 0.62), Offset(r.left + w * 0.6, r.top + h * 0.62)], Pk.fill(Pk.dark(a, 0.15)));
  c.drawPath(body, Pk.fill(a));
  Pk.poly(c, [Offset(r.right - w * 0.22, r.top + h * 0.28), Offset(r.right - w * 0.1, r.top + h * 0.05), Offset(r.right - w * 0.05, r.top + h * 0.05), Offset(r.right - w * 0.08, r.top + h * 0.3)], Pk.fill(Pk.dark(a, 0.1)));
  c.drawPath(Path()..moveTo(r.left + w * 0.05, r.top + h * 0.42)..lineTo(r.right, r.top + h * 0.5)..lineTo(r.left + w * 0.12, r.top + h * 0.52)..close(), Pk.fill(_ebony));
  c.drawRect(Rect.fromLTWH(r.left + w * 0.14, r.top + h * 0.3, w * 0.1, h * 0.06), Pk.fill(_cyan));
  c.drawRect(Rect.fromLTWH(r.left + w * 0.35, r.top + h * 0.34, w * 0.4, h * 0.04), Pk.fill(b));
}

