void _earth(Canvas c, Offset p, double rad, double ov) {
  Pk.glow(c, p, rad * 1.5, const Color(0xFF7FD0FF), 0.35 * ov + 0.1);
  c.drawCircle(p, rad, Pk.fill(Pk.mix(const Color(0xFF7890A0), const Color(0xFF2E8FE0), ov)));
  final land = Pk.fill(Pk.mix(const Color(0xFF8A9A80), const Color(0xFF4FC94A), ov));
  c.save();
  c.clipPath(Path()..addOval(Rect.fromCircle(center: p, radius: rad)));
  c.drawOval(Rect.fromCenter(center: p + Offset(-rad * 0.3, -rad * 0.2), width: rad * 0.9, height: rad * 0.6), land);
  c.drawOval(Rect.fromCenter(center: p + Offset(rad * 0.4, rad * 0.35), width: rad * 0.7, height: rad * 0.5), land);
  c.drawOval(Rect.fromCenter(center: p + Offset(rad * 0.1, -rad * 0.75), width: rad * 1.4, height: rad * 0.35), Pk.fill(Colors.white.withValues(alpha: 0.7)));
  c.drawCircle(p + Offset(rad * 0.45, rad * 0.1), rad * 1.05, Pk.fill(Colors.black.withValues(alpha: 0.28)));
  c.restore();
}

void _moonBase(Canvas c, double ov, double t) {
  c.drawRect(const Rect.fromLTWH(0, 0, 400, 152), _vgrad(const Rect.fromLTWH(0, 0, 400, 152), Pk.mix(const Color(0xFF3A3A4A), const Color(0xFF0E1230), ov), Pk.mix(const Color(0xFF5A5A6A), const Color(0xFF2A2458), ov)));
  _stars(c, const Rect.fromLTWH(0, 0, 400, 130), 40, ov, t);
  _earth(c, const Offset(70, 44), 22, ov);
  final dome = Pk.mix(const Color(0xFF8A8E9A), const Color(0xFFDDE6F4), ov);
  for (final (x, rad) in [(270.0, 24.0), (318.0, 16.0)]) {
    c.drawArc(Rect.fromCircle(center: Offset(x, 146), radius: rad), pi, pi, true, Pk.fill(dome));
    c.drawArc(Rect.fromCircle(center: Offset(x, 146), radius: rad * 0.7), pi * 1.15, pi * 0.3, false, Pk.stroke(Colors.white.withValues(alpha: 0.6), 2));
  }
  c.drawRect(const Rect.fromLTWH(292, 140, 14, 6), Pk.fill(dome));
  final ridge = Path()
    ..moveTo(0, 146)
    ..quadraticBezierTo(60, 128, 130, 142)
    ..quadraticBezierTo(180, 134, 230, 146)
    ..lineTo(230, 152)
    ..lineTo(0, 152)
    ..close();
  c.drawPath(ridge, Pk.fill(Pk.mix(const Color(0xFF7A7A80), const Color(0xFF8E8AA8), ov)));
  for (final (x, y, s) in [(40.0, 200.0, 30.0), (250.0, 222.0, 40.0), (330.0, 176.0, 22.0), (150.0, 186.0, 16.0)]) {
    c.drawOval(Rect.fromCenter(center: Offset(x, y), width: s, height: s * 0.3), Pk.fill(Colors.black.withValues(alpha: 0.18)));
    c.drawArc(Rect.fromCenter(center: Offset(x, y), width: s, height: s * 0.3), 0.2, pi - 0.4, false, Pk.stroke(Colors.white.withValues(alpha: 0.25), 1.2));
  }
}

void _panelWall(Canvas c, double ov, double t) {
  final line = Pk.stroke(Colors.black.withValues(alpha: 0.1), 1);
  for (var x = 0; x < 9; x++) {
    c.drawLine(Offset(x * 50.0, 0), Offset(x * 50.0, 166), line);
  }
  c.drawLine(const Offset(0, 100), const Offset(400, 100), line);
  for (var x = 0; x < 9; x++) {
    for (final y in [8.0, 92.0, 108.0, 158.0]) {
      c.drawCircle(Offset(x * 50.0 + 6, y), 1.2, Pk.fill(Colors.black.withValues(alpha: 0.15)));
    }
  }
  final strip = const Rect.fromLTWH(0, 160, 400, 4);
  c.drawRect(strip, Pk.fill(Pk.mix(const Color(0xFF8A8E9A), _cyan, ov).withValues(alpha: 0.7)));
}

void _greenDome(Canvas c, double ov, double t) {
  final sky = const Rect.fromLTWH(0, 0, 400, 150);
  c.drawRect(sky, _vgrad(sky, Pk.mix(const Color(0xFF4A4E5A), const Color(0xFF0E1230), ov), Pk.mix(const Color(0xFF6E727A), const Color(0xFF2E2A60), ov)));
  _stars(c, const Rect.fromLTWH(0, 0, 400, 140), 36, ov, t, 5);
  c.drawCircle(const Offset(330, 40), 16, Pk.fill(Pk.mix(const Color(0xFFBDB6A4), const Color(0xFFE8E2D0), ov)));
  final frame = Pk.stroke(Pk.mix(const Color(0xFF8A8E9A), const Color(0xFFE6EEF6), ov), 2.5);
  final dome = Rect.fromLTWH(-60, -20, 520, 340);
  c.drawArc(dome, pi, pi, false, frame);
  for (var i = 1; i < 8; i++) {
    final x = i * 50.0;
    c.drawLine(Offset(x, 150), Offset(200 + (x - 200) * 0.4, -10), frame);
  }
  for (final y in [50.0, 100.0]) {
    c.drawLine(Offset(0, y), Offset(400, y), frame);
  }
  c.drawRect(const Rect.fromLTWH(0, 146, 400, 26), Pk.fill(Pk.mix(const Color(0xFF8A8E9A), const Color(0xFFDDE6F0), ov)));
  c.drawRect(const Rect.fromLTWH(0, 146, 400, 3), Pk.fill(Pk.mix(const Color(0xFF6E7285), _emerald, ov)));
}

void _quartersWall(Canvas c, double ov, double t) {
  _panelWall(c, ov, t);
  final shelf = Pk.mix(const Color(0xFF8A8E9A), const Color(0xFFFFB35C), ov);
  c.drawRect(const Rect.fromLTWH(150, 38, 120, 4), Pk.fill(shelf));
}

void _panorama(Canvas c, double ov, double t) {
  final win = const Rect.fromLTWH(70, 10, 260, 132);
  final rr = RRect.fromRectAndRadius(win, const Radius.circular(40));
  c.drawRRect(rr.inflate(6), Pk.fill(Pk.mix(const Color(0xFF6E7285), const Color(0xFFC9CCD8), ov)));
  c.save();
  c.clipRRect(rr);
  c.drawRect(win, _vgrad(win, const Color(0xFF060818), Pk.mix(const Color(0xFF2A2A3A), const Color(0xFF1E1650), ov)));
  _stars(c, win, 50, 0.4 + 0.6 * ov, t, 11);
  _earth(c, Offset(200 + sin(t * 0.05) * 4, 150), 76, ov);
  c.restore();
  for (final x in [156.0, 244.0]) {
    c.drawRect(Rect.fromLTWH(x - 2, 8, 4, 136), Pk.fill(Pk.mix(const Color(0xFF6E7285), const Color(0xFFC9CCD8), ov)));
  }
  c.drawRRect(rr, Pk.stroke(Colors.white.withValues(alpha: 0.3), 1.5));
}

// =============================================================== GRAND HOTEL

void _paintRevolvingDoor(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  Pk.box(c, Rect.fromLTWH(r.left, r.top, w, h * 0.12), b, radius: 2);
  final glass = Rect.fromLTWH(r.left + w * 0.06, r.top + h * 0.12, w * 0.88, h * 0.82);
  c.drawRect(glass, _vgrad(glass, const Color(0xFFBFEFFA).withValues(alpha: 0.85), const Color(0xFF8ED8FF).withValues(alpha: 0.7)));
  Pk.glow(c, glass.center, w * 0.6, _lampGlow, 0.3);
  final ph = t * 0.6;
  for (var i = 0; i < 4; i++) {
    final x = glass.center.dx + sin(ph + i * pi / 2) * glass.width * 0.42;
    c.drawLine(Offset(x, glass.top + 2), Offset(x, glass.bottom - 2), Pk.stroke(b, cos(ph + i * pi / 2) > 0 ? 2.5 : 1.2));
  }
  c.drawLine(Offset(glass.center.dx, glass.top), Offset(glass.center.dx, glass.bottom), Pk.stroke(b, 3));
  c.drawRect(glass, Pk.stroke(b, 2.5));
  Pk.box(c, Rect.fromLTWH(r.left - w * 0.02, r.bottom - h * 0.06, w * 1.04, h * 0.06), b, radius: 2);
  c.drawLine(Offset(glass.left + w * 0.1, glass.top + h * 0.1), Offset(glass.left + w * 0.25, glass.top + h * 0.02 + h * 0.06), Pk.stroke(Colors.white.withValues(alpha: 0.6), 2));
}

void _paintCanopy(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  Pk.poly(c, [Offset(r.left + w * 0.05, r.top), Offset(r.right - w * 0.05, r.top), Offset(r.right, r.top + h * 0.6), Offset(r.left, r.top + h * 0.6)], Pk.fill(a));
  final n = 9;
  for (var i = 0; i < n; i++) {
    final x0 = r.left + w * i / n, x1 = r.left + w * (i + 1) / n;
    c.drawArc(Rect.fromLTWH(x0, r.top + h * 0.45, x1 - x0, h * 0.3), 0, pi, true, Pk.fill(i.isEven ? a : Pk.dark(a, 0.12)));
  }
  c.drawRect(Rect.fromLTWH(r.left, r.top + h * 0.5, w, h * 0.1), Pk.fill(b));
  for (var i = 0; i < 12; i++) {
    final on = (i + (t * 4).floor()) % 3 != 0;
    final p = Offset(r.left + w * (i + 0.5) / 12, r.top + h * 0.55);
    if (on) Pk.glow(c, p, 5, _lampGlow, 0.6);
    c.drawCircle(p, 1.6, Pk.fill(on ? _lampGlow : Pk.dark(b, 0.3)));
  }
  for (final x in [0.08, 0.92]) {
    c.drawLine(Offset(r.left + w * x, r.top + h * 0.6), Offset(r.left + w * x, r.bottom), Pk.stroke(b, 2));
  }
}

void _paintRedCarpet(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  Pk.poly(c, [Offset(r.center.dx - w * 0.2, r.top), Offset(r.center.dx + w * 0.2, r.top), Offset(r.right - w * 0.12, r.bottom), Offset(r.left + w * 0.12, r.bottom)], Pk.fill(a));
  Pk.poly(c, [Offset(r.center.dx - w * 0.17, r.top), Offset(r.center.dx + w * 0.17, r.top), Offset(r.right - w * 0.17, r.bottom), Offset(r.left + w * 0.17, r.bottom)], Pk.fill(Pk.light(a, 0.08)));
  for (final d in [-1.0, 1.0]) {
    final top = Offset(r.center.dx + d * w * 0.32, r.top + h * 0.1);
    final bot = Offset(r.center.dx + d * w * 0.46, r.bottom - h * 0.25);
    final rope = Path()
      ..moveTo(top.dx, top.dy)
      ..quadraticBezierTo((top.dx + bot.dx) / 2 + d * 3, (top.dy + bot.dy) / 2 + h * 0.08, bot.dx, bot.dy);
    c.drawPath(rope, Pk.stroke(_crimson, 2.2));
    for (final p in [top, bot]) {
      final ph = (p.dy - r.top) / h;
      final ps = 1 + ph;
      c.drawRect(Rect.fromLTWH(p.dx - 1.2 * ps, p.dy, 2.4 * ps, h * 0.12 * ps), Pk.fill(b));
      c.drawCircle(p, 2.2 * ps, Pk.fill(Pk.light(b, 0.2)));
    }
  }
}

void _paintBellCart(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  final bar = Pk.stroke(b, 2.2);
  c.drawArc(Rect.fromLTWH(r.left + w * 0.05, r.top, w * 0.9, h * 0.4), pi, pi, false, bar);
  c.drawLine(Offset(r.left + w * 0.05, r.top + h * 0.2), Offset(r.left + w * 0.05, r.bottom - h * 0.16), bar);
  c.drawLine(Offset(r.right - w * 0.05, r.top + h * 0.2), Offset(r.right - w * 0.05, r.bottom - h * 0.16), bar);
  Pk.box(c, Rect.fromLTWH(r.left + w * 0.12, r.top + h * 0.38, w * 0.4, h * 0.42), a, radius: 3);
  Pk.box(c, Rect.fromLTWH(r.left + w * 0.5, r.top + h * 0.52, w * 0.38, h * 0.28), Pk.dark(a, 0.2), radius: 3);
  Pk.box(c, Rect.fromLTWH(r.left + w * 0.2, r.top + h * 0.26, w * 0.28, h * 0.14), _cream, radius: 2);
  Pk.box(c, Rect.fromLTWH(r.left, r.bottom - h * 0.2, w, h * 0.06), b, radius: 2);
  for (final x in [0.15, 0.85]) {
    c.drawCircle(Offset(r.left + w * x, r.bottom - h * 0.07), h * 0.07, Pk.fill(const Color(0xFF2A2440)));
  }
}

void _paintReception(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  Pk.box(c, Rect.fromLTWH(r.left, r.top + h * 0.2, w, h * 0.8), a, radius: 3);
  for (var i = 0; i < 4; i++) {
    final pnl = Rect.fromLTWH(r.left + w * (0.05 + i * 0.235), r.top + h * 0.38, w * 0.2, h * 0.5);
    c.drawRect(pnl, Pk.stroke(b, 1.5));
  }
  Pk.box(c, Rect.fromLTWH(r.left - w * 0.03, r.top + h * 0.14, w * 1.06, h * 0.12), _marble, radius: 2);
  c.drawRect(Rect.fromLTWH(r.left - w * 0.03, r.top + h * 0.25, w * 1.06, h * 0.04), Pk.fill(b));
  final bell = Offset(r.left + w * 0.7, r.top + h * 0.14);
  c.drawArc(Rect.fromCenter(center: bell, width: w * 0.1, height: h * 0.18), pi, pi, true, Pk.fill(b));
  c.drawCircle(bell - Offset(0, h * 0.1), 1.6, Pk.fill(b));
  Pk.box(c, Rect.fromLTWH(r.left + w * 0.18, r.top, w * 0.16, h * 0.16), _cream, radius: 1);
  c.drawLine(Offset(r.left + w * 0.2, r.top + h * 0.05), Offset(r.left + w * 0.32, r.top + h * 0.05), Pk.stroke(_navy, 0.8));
}

void _paintElevator(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  Pk.box(c, Rect.fromLTWH(r.left, r.top + h * 0.12, w, h * 0.88), b, radius: 2);
  final doors = Rect.fromLTWH(r.left + w * 0.1, r.top + h * 0.24, w * 0.8, h * 0.76);
  c.drawRect(doors, Pk.fill(a));
  c.drawLine(doors.topCenter, doors.bottomCenter, Pk.stroke(Pk.dark(a, 0.35), 1.5));
  for (final d in [0.25, 0.75]) {
    final x = doors.left + doors.width * d;
    final dia = Path()
      ..moveTo(x, doors.top + doors.height * 0.2)
      ..lineTo(x + doors.width * 0.12, doors.top + doors.height * 0.4)
      ..lineTo(x, doors.top + doors.height * 0.6)
      ..lineTo(x - doors.width * 0.12, doors.top + doors.height * 0.4)
      ..close();
    c.drawPath(dia, Pk.stroke(Pk.light(a, 0.3), 1.2));
  }
  final dial = Rect.fromLTWH(r.left + w * 0.2, r.top, w * 0.6, h * 0.24);
  c.drawArc(dial, pi, pi, true, Pk.fill(b));
  c.drawArc(dial.deflate(3), pi, pi, true, Pk.fill(_cream));
  final ang = pi + (0.5 + 0.5 * sin(t * 0.7)) * pi;
  c.drawLine(dial.center, dial.center + Offset(cos(ang), sin(ang)) * dial.width * 0.35, Pk.stroke(_ebony, 1.2));
  c.drawCircle(Offset(r.right - w * 0.04, r.top + h * 0.55), 2, Pk.fill(sin(t * 2) > 0 ? _gold : Pk.dark(_gold, 0.4)));
}

void _paintTopiary(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  Pk.poly(c, [Offset(r.left + w * 0.2, r.bottom - h * 0.22), Offset(r.right - w * 0.2, r.bottom - h * 0.22), Offset(r.right - w * 0.28, r.bottom), Offset(r.left + w * 0.28, r.bottom)], Pk.fill(b));
  c.drawRect(Rect.fromLTWH(r.left + w * 0.16, r.bottom - h * 0.25, w * 0.68, h * 0.05), Pk.fill(Pk.dark(b, 0.15)));
  c.drawRect(Rect.fromLTWH(r.center.dx - w * 0.04, r.top + h * 0.5, w * 0.08, h * 0.3), Pk.fill(const Color(0xFF7A4E30)));
  final rad = min(w * 0.45, h * 0.28);
  c.drawCircle(Offset(r.center.dx, r.top + rad), rad, Pk.fill(a));
  c.drawCircle(Offset(r.center.dx, r.top + h * 0.5), rad * 0.6, Pk.fill(Pk.dark(a, 0.06)));
  c.drawCircle(Offset(r.center.dx - rad * 0.35, r.top + rad * 0.6), rad * 0.3, Pk.fill(Pk.light(a, 0.2)));
}

void _paintJewelryBox(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  Pk.poly(c, [Offset(r.left + w * 0.05, r.top + h * 0.42), Offset(r.right - w * 0.05, r.top + h * 0.42), Offset(r.right - w * 0.1, r.top), Offset(r.left + w * 0.1, r.top)], Pk.fill(Pk.dark(a, 0.15)));
  c.drawRect(Rect.fromLTWH(r.left + w * 0.14, r.top + h * 0.06, w * 0.72, h * 0.3), Pk.fill(_crimson));
  Pk.box(c, Rect.fromLTWH(r.left, r.top + h * 0.45, w, h * 0.55), a, radius: 3);
  c.drawRect(Rect.fromLTWH(r.left, r.top + h * 0.45, w, h * 0.06), Pk.fill(b));
  for (final (x, col) in [(0.3, _ruby), (0.5, _emerald), (0.7, _blue)]) {
    c.drawCircle(Offset(r.left + w * x, r.top + h * 0.43), w * 0.06, Pk.fill(col));
  }
  Pk.sparkle(c, Offset(r.left + w * 0.5, r.top + h * 0.3), 2.5 + sin(t * 3) * 1.5, Colors.white);
  c.drawCircle(Offset(r.center.dx, r.top + h * 0.72), w * 0.04, Pk.fill(b));
}

const _revolvingDoor = CustomProp(_paintRevolvingDoor);
const _canopy = CustomProp(_paintCanopy, wall: true);
const _redCarpet = CustomProp(_paintRedCarpet);
const _bellCart = CustomProp(_paintBellCart);
const _reception = CustomProp(_paintReception);
const _elevator = CustomProp(_paintElevator);
const _topiary = CustomProp(_paintTopiary);
const _jewelryBox = CustomProp(_paintJewelryBox);

void _hotelFacade(Canvas c, double ov, double t) {
  final wall = Pk.mix(const Color(0xFFB5A99A), const Color(0xFFFFF0DC), ov);
  final trim = Pk.mix(const Color(0xFF8C7E6C), const Color(0xFFC98A52), ov);
  c.drawRect(const Rect.fromLTWH(20, 0, 360, 150), Pk.fill(wall));
  c.drawRect(const Rect.fromLTWH(20, 52, 360, 4), Pk.fill(trim));
  for (var y = 0; y < 2; y++) {
    for (var x = 0; x < 8; x++) {
      if (y == 1 && (x == 3 || x == 4)) continue;
      final win = Rect.fromLTWH(36 + x * 44.0, 12 + y * 54.0, 24, 32);
      c.drawRRect(RRect.fromRectAndCorners(win, topLeft: const Radius.circular(12), topRight: const Radius.circular(12)), Pk.fill(Pk.mix(const Color(0xFF6E7A80), const Color(0xFFFFE3A0), ov)));
      c.drawLine(win.topCenter + const Offset(0, 4), win.bottomCenter, Pk.stroke(trim, 1.2));
      c.drawRect(Rect.fromLTWH(win.left - 3, win.bottom, win.width + 6, 3), Pk.fill(trim));
    }
  }
  for (final x in [124.0, 268.0]) {
    Pk.box(c, Rect.fromLTWH(x, 56, 10, 94), Pk.light(wall, 0.3), radius: 1);
  }
  c.drawRect(const Rect.fromLTWH(14, 0, 372, 4), Pk.fill(trim));
  for (final x in [10.0, 374.0]) {
    Pk.box(c, Rect.fromLTWH(x, 0, 16, 150), Pk.dark(wall, 0.08), radius: 1);
  }
}

void _lobbyHall(Canvas c, double ov, double t) {
  final gold = Pk.mix(const Color(0xFF9A8C7A), _brass, ov);
  for (final x in [100.0, 290.0]) {
    Pk.box(c, Rect.fromLTWH(x, 14, 12, 152), Pk.mix(const Color(0xFFB8B0A4), _marble, ov), radius: 1);
    c.drawRect(Rect.fromLTWH(x - 3, 14, 18, 5), Pk.fill(gold));
    c.drawRect(Rect.fromLTWH(x - 3, 160, 18, 6), Pk.fill(gold));
  }
  c.drawRect(const Rect.fromLTWH(0, 10, 400, 4), Pk.fill(gold));
  for (var i = 0; i < 20; i++) {
    c.drawLine(Offset(i * 20.0, 14), Offset(i * 20.0 + 10, 22), Pk.stroke(gold.withValues(alpha: 0.4), 1));
  }
}

void _ballroomWall(Canvas c, double ov, double t) {
  final gold = Pk.mix(const Color(0xFF9A8C7A), _brass, ov);
  for (var i = 0; i < 6; i++) {
    final p = Rect.fromLTWH(8 + i * 66.0, 70, 52, 80);
    c.drawRRect(RRect.fromRectAndRadius(p, const Radius.circular(3)), Pk.stroke(gold.withValues(alpha: 0.7), 1.5));
  }
  c.drawRect(const Rect.fromLTWH(0, 60, 400, 3), Pk.fill(gold));
}

void _suiteWall(Canvas c, double ov, double t) {
  final s = Pk.mix(const Color(0xFF9A9090), const Color(0xFFD6C2F0), ov);
  for (var i = 0; i < 20; i++) {
    c.drawRect(Rect.fromLTWH(i * 20.0, 0, 8, 166), Pk.fill(s.withValues(alpha: 0.35)));
  }
  c.drawRect(const Rect.fromLTWH(0, 116, 400, 4), Pk.fill(Pk.mix(const Color(0xFF8A8078), _brass, ov)));
}

void _rooftopDeck(Canvas c, double ov, double t) {
  final glass = Pk.mix(const Color(0xFF8A8E9A), const Color(0xFF9CE0FF), ov);
  c.drawRect(const Rect.fromLTWH(0, 128, 400, 22), Pk.fill(glass.withValues(alpha: 0.25)));
  c.drawRect(const Rect.fromLTWH(0, 126, 400, 3), Pk.fill(Pk.mix(const Color(0xFF8A8E9A), _steel, ov)));
  for (var i = 0; i < 9; i++) {
    c.drawRect(Rect.fromLTWH(i * 50.0, 126, 2, 24), Pk.fill(Pk.mix(const Color(0xFF8A8E9A), _steel, ov)));
  }
}

// =============================================================== ROYAL PALACE

void _paintGoldGate(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  for (final x in [r.left, r.right - w * 0.12]) {
    Pk.box(c, Rect.fromLTWH(x, r.top + h * 0.16, w * 0.12, h * 0.84), b, radius: 2);
    c.drawCircle(Offset(x + w * 0.06, r.top + h * 0.12), w * 0.05, Pk.fill(a));
    Pk.poly(c, [Offset(x + w * 0.02, r.top + h * 0.1), Offset(x + w * 0.06, r.top), Offset(x + w * 0.1, r.top + h * 0.1)], Pk.fill(a));
  }
  final inner = Rect.fromLTWH(r.left + w * 0.12, r.top + h * 0.2, w * 0.76, h * 0.8);
  final bar = Pk.stroke(a, 2);
  for (var i = 1; i < 12; i++) {
    final x = inner.left + inner.width * i / 12;
    final top = inner.top + inner.height * 0.18 * (1 - sin(pi * i / 12));
    c.drawLine(Offset(x, inner.bottom), Offset(x, top), bar);
    Pk.poly(c, [Offset(x - 2.5, top + 3), Offset(x, top - 4), Offset(x + 2.5, top + 3)], Pk.fill(a));
  }
  final arch = Path()
    ..moveTo(inner.left, inner.top + inner.height * 0.2)
    ..quadraticBezierTo(inner.center.dx, inner.top - inner.height * 0.12, inner.right, inner.top + inner.height * 0.2);
  c.drawPath(arch, Pk.stroke(a, 3));
  for (final y in [0.45, 0.85]) {
    c.drawLine(Offset(inner.left, inner.top + inner.height * y), Offset(inner.right, inner.top + inner.height * y), Pk.stroke(a, 2.5));
  }
  c.drawLine(Offset(inner.center.dx, inner.top + inner.height * 0.1), Offset(inner.center.dx, inner.bottom), Pk.stroke(a, 3));
  final crest = Offset(inner.center.dx, inner.top + inner.height * 0.3);
  c.drawCircle(crest, w * 0.07, Pk.fill(a));
  c.drawCircle(crest, w * 0.045, Pk.fill(_crimson));
  Pk.sparkle(c, crest + Offset(-w * 0.03, -w * 0.03), 2 + sin(t * 3) * 1.2, Colors.white);
  for (var i = 0; i < 4; i++) {
    final cx = inner.left + inner.width * (0.15 + i * 0.233);
    c.drawCircle(Offset(cx, inner.top + inner.height * 0.65), inner.width * 0.05, Pk.stroke(a, 1.5));
  }
}

void _paintGuardBox(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  Pk.box(c, Rect.fromLTWH(r.left + w * 0.08, r.top + h * 0.22, w * 0.84, h * 0.78), a, radius: 2);
  final door = Rect.fromLTWH(r.left + w * 0.24, r.top + h * 0.36, w * 0.52, h * 0.6);
  c.drawRRect(RRect.fromRectAndCorners(door, topLeft: Radius.circular(w * 0.26), topRight: Radius.circular(w * 0.26)), Pk.fill(Pk.dark(a, 0.45)));
  for (var i = 0; i < 4; i++) {
    c.drawRect(Rect.fromLTWH(r.left + w * 0.08, r.top + h * (0.24 + i * 0.2), w * 0.84, h * 0.05), Pk.fill(i.isEven ? b : Pk.dark(a, 0.1)));
  }
  Pk.poly(c, [Offset(r.left, r.top + h * 0.24), Offset(r.center.dx, r.top), Offset(r.right, r.top + h * 0.24)], Pk.fill(b));
  c.drawCircle(Offset(r.center.dx, r.top + h * 0.02), w * 0.06, Pk.fill(_gold));
}

void _paintShield(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  final p = Path()
    ..moveTo(r.left, r.top)
    ..lineTo(r.right, r.top)
    ..lineTo(r.right, r.top + h * 0.45)
    ..quadraticBezierTo(r.right, r.bottom - h * 0.15, r.center.dx, r.bottom)
    ..quadraticBezierTo(r.left, r.bottom - h * 0.15, r.left, r.top + h * 0.45)
    ..close();
  c.drawPath(p, Pk.fill(a));
  c.save();
  c.clipPath(p);
  c.drawRect(Rect.fromLTWH(r.center.dx - w * 0.1, r.top, w * 0.2, h), Pk.fill(b));
  c.drawRect(Rect.fromLTWH(r.left, r.top + h * 0.32, w, h * 0.16), Pk.fill(b));
  c.restore();
  c.drawPath(p, Pk.stroke(Pk.dark(b, 0.2), 2));
  c.drawCircle(Offset(r.center.dx, r.top + h * 0.4), w * 0.1, Pk.fill(Pk.light(b, 0.3)));
}

void _paintCrownCushion(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  Pk.box(c, Rect.fromLTWH(r.left + w * 0.3, r.top + h * 0.55, w * 0.4, h * 0.45), _marble, radius: 2);
  Pk.box(c, Rect.fromLTWH(r.left + w * 0.2, r.top + h * 0.52, w * 0.6, h * 0.07), Pk.dark(_marble, 0.08), radius: 2);
  Pk.box(c, Rect.fromLTWH(r.left + w * 0.2, r.bottom - h * 0.08, w * 0.6, h * 0.08), Pk.dark(_marble, 0.08), radius: 2);
  c.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(r.left + w * 0.08, r.top + h * 0.38, w * 0.84, h * 0.16), Radius.circular(h * 0.08)), Pk.fill(a));
  for (final x in [0.1, 0.9]) {
    c.drawCircle(Offset(r.left + w * x, r.top + h * 0.48), w * 0.04, Pk.fill(b));
  }
  final base = r.top + h * 0.38;
  final crown = Path()
    ..moveTo(r.left + w * 0.24, base)
    ..lineTo(r.left + w * 0.2, r.top + h * 0.08)
    ..lineTo(r.left + w * 0.36, r.top + h * 0.2)
    ..lineTo(r.center.dx, r.top)
    ..lineTo(r.right - w * 0.36, r.top + h * 0.2)
    ..lineTo(r.right - w * 0.2, r.top + h * 0.08)
    ..lineTo(r.right - w * 0.24, base)
    ..close();
  Pk.glow(c, Offset(r.center.dx, r.top + h * 0.2), w * 0.6, b, 0.35);
  c.drawPath(crown, Pk.fill(b));
  c.drawRect(Rect.fromLTWH(r.left + w * 0.24, base - h * 0.08, w * 0.52, h * 0.08), Pk.fill(Pk.dark(b, 0.12)));
  for (final (x, col) in [(0.36, _ruby), (0.5, _emerald), (0.64, _blue)]) {
    c.drawCircle(Offset(r.left + w * x, base - h * 0.04), w * 0.035, Pk.fill(col));
  }
  for (final x in [0.2, 0.5, 0.8]) {
    c.drawCircle(Offset(r.left + w * x, r.top + h * (x == 0.5 ? 0.0 : 0.08)), w * 0.03, Pk.fill(Colors.white));
  }
  Pk.sparkle(c, Offset(r.center.dx + w * 0.1, r.top + h * 0.12), 2.5 + 1.5 * sin(t * 3), Colors.white);
}

void _paintOrb(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  Pk.poly(c, [Offset(r.left + w * 0.3, r.top + h * 0.6), Offset(r.right - w * 0.3, r.top + h * 0.6), Offset(r.right - w * 0.15, r.bottom), Offset(r.left + w * 0.15, r.bottom)], Pk.fill(Pk.dark(_marble, 0.05)));
  Pk.box(c, Rect.fromLTWH(r.left + w * 0.1, r.bottom - h * 0.08, w * 0.8, h * 0.08), Pk.dark(_marble, 0.12), radius: 2);
  final cc = Offset(r.center.dx, r.top + h * 0.42);
  final rad = w * 0.3;
  Pk.glow(c, cc, rad * 1.8, b, 0.3);
  c.drawCircle(cc, rad, Pk.fill(b));
  c.drawLine(cc - Offset(rad, 0), cc + Offset(rad, 0), Pk.stroke(Pk.dark(b, 0.25), 2));
  c.drawLine(cc - Offset(0, rad), cc + Offset(0, rad), Pk.stroke(Pk.dark(b, 0.25), 2));
  c.drawCircle(cc + Offset(0, 0), rad * 0.18, Pk.fill(a));
  c.drawCircle(cc + Offset(-rad * 0.35, -rad * 0.4), rad * 0.2, Pk.fill(Colors.white.withValues(alpha: 0.5)));
  c.drawLine(cc - Offset(0, rad), cc - Offset(0, rad * 1.6), Pk.stroke(b, 2.5));
  c.drawLine(cc - Offset(rad * 0.3, rad * 1.35), cc - Offset(-rad * 0.3, rad * 1.35), Pk.stroke(b, 2.5));
}

void _paintLectern(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  Pk.box(c, Rect.fromLTWH(r.left + w * 0.25, r.bottom - h * 0.08, w * 0.5, h * 0.08), Pk.dark(a, 0.2), radius: 2);
  c.drawRect(Rect.fromLTWH(r.center.dx - w * 0.07, r.top + h * 0.4, w * 0.14, h * 0.55), Pk.fill(a));
  Pk.poly(c, [Offset(r.left, r.top + h * 0.42), Offset(r.left + w * 0.08, r.top + h * 0.22), Offset(r.right - w * 0.08, r.top + h * 0.22), Offset(r.right, r.top + h * 0.42)], Pk.fill(Pk.dark(a, 0.1)));
  Pk.poly(c, [Offset(r.left + w * 0.06, r.top + h * 0.36), Offset(r.left + w * 0.14, r.top + h * 0.14), Offset(r.center.dx, r.top + h * 0.18), Offset(r.center.dx, r.top + h * 0.4)], Pk.fill(_cream));
  Pk.poly(c, [Offset(r.right - w * 0.06, r.top + h * 0.36), Offset(r.right - w * 0.14, r.top + h * 0.14), Offset(r.center.dx, r.top + h * 0.18), Offset(r.center.dx, r.top + h * 0.4)], Pk.fill(Pk.dark(_cream, 0.06)));
  c.drawRect(Rect.fromLTWH(r.left + w * 0.04, r.top + h * 0.36, w * 0.92, h * 0.05), Pk.fill(b));
  Pk.box(c, Rect.fromLTWH(r.center.dx - w * 0.08, r.top + h * 0.2, w * 0.16, h * 0.14), b, radius: 2);
  c.drawArc(Rect.fromLTWH(r.center.dx - w * 0.05, r.top + h * 0.12, w * 0.1, h * 0.12), pi, pi, false, Pk.stroke(b, 1.5));
  for (var i = 0; i < 3; i++) {
    c.drawLine(Offset(r.left + w * 0.18, r.top + h * (0.22 + i * 0.04)), Offset(r.left + w * 0.38, r.top + h * (0.24 + i * 0.04)), Pk.stroke(_navy.withValues(alpha: 0.5), 0.8));
  }
}

void _paintGlobe(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  for (final x in [0.2, 0.8]) {
    c.drawLine(Offset(r.left + w * x, r.bottom), Offset(r.center.dx, r.top + h * 0.7), Pk.stroke(Pk.dark(b, 0.2), 2));
  }
  final cc = Offset(r.center.dx, r.top + h * 0.38);
  final rad = min(w * 0.4, h * 0.34);
  c.drawCircle(cc, rad, Pk.fill(a));
  c.save();
  c.clipPath(Path()..addOval(Rect.fromCircle(center: cc, radius: rad)));
  final sh = (t * 6) % (rad * 2);
  for (final (dx, dy, s) in [(-0.3, -0.2, 0.6), (0.4, 0.3, 0.5), (-0.1, 0.5, 0.3)]) {
    c.drawOval(Rect.fromCenter(center: cc + Offset(dx * rad + sh - rad, dy * rad), width: rad * s * 1.4, height: rad * s), Pk.fill(_moss));
    c.drawOval(Rect.fromCenter(center: cc + Offset(dx * rad + sh + rad, dy * rad), width: rad * s * 1.4, height: rad * s), Pk.fill(_moss));
  }
  c.restore();
  c.drawArc(Rect.fromCircle(center: cc, radius: rad + 3), -pi * 0.6, pi * 1.2, false, Pk.stroke(b, 2));
}

void _paintFireworks(Canvas c, Rect r, Color a, Color b, double t) {
  final cc = r.center;
  final rad = min(r.width, r.height) / 2;
  final k = (t * 0.5 + r.left * 0.013) % 1;
  final fade = (1 - k).clamp(0.0, 1.0);
  final rr = rad * (0.4 + 0.6 * Curves.easeOut.transform(k));
  Pk.glow(c, cc, rr * 1.2, a, 0.25 * fade);
  for (var i = 0; i < 12; i++) {
    final ang = i * pi / 6;
    final p0 = cc + Offset(cos(ang), sin(ang)) * rr * 0.35;
    final p1 = cc + Offset(cos(ang), sin(ang)) * rr;
    c.drawLine(p0, p1, Pk.stroke((i.isEven ? a : b).withValues(alpha: 0.4 + 0.6 * fade), 1.6));
    c.drawCircle(p1, 1.8, Pk.fill(Colors.white.withValues(alpha: fade)));
  }
  c.drawCircle(cc, 2.5, Pk.fill(Colors.white.withValues(alpha: 0.8 * fade)));
}

void _paintArchWindow(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  final outer = _archPath(r.inflate(3), 0.5);
  c.drawPath(outer, Pk.fill(a));
  final glass = _archPath(r, 0.5);
  c.drawPath(glass, Pk.fill(b));
  c.save();
  c.clipPath(glass);
  for (var i = 0; i < 6; i++) {
    final cc = Offset(r.left + w * (0.25 + (i % 2) * 0.5), r.top + h * (0.25 + (i ~/ 2) * 0.25));
    c.drawCircle(cc, w * 0.16, Pk.fill([_ruby, _gold, _blue, _emerald, _purple, _gold][i].withValues(alpha: 0.45)));
  }
  c.restore();
  c.drawLine(Offset(r.center.dx, r.top + 2), Offset(r.center.dx, r.bottom), Pk.stroke(a, 2));
  for (final y in [0.45, 0.72]) {
    c.drawLine(Offset(r.left, r.top + h * y), Offset(r.right, r.top + h * y), Pk.stroke(a, 2));
  }
  c.drawLine(Offset(r.left + w * 0.2, r.top + h * 0.5), Offset(r.left + w * 0.35, r.top + h * 0.3), Pk.stroke(Colors.white.withValues(alpha: 0.5), 2));
}

void _paintRollingLadder(Canvas c, Rect r, Color a, Color b, double t) {
  final w = r.width, h = r.height;
  final rail = Pk.stroke(a, 3);
  c.drawLine(Offset(r.left + w * 0.3, r.top), Offset(r.left, r.bottom - 3), rail);
  c.drawLine(Offset(r.right, r.top), Offset(r.right - w * 0.3, r.bottom - 3), rail);
  for (var i = 1; i < 8; i++) {
    final k = i / 8;
    c.drawLine(Offset(r.left + w * 0.3 * (1 - k), r.top + h * k), Offset(r.right - w * 0.3 * k, r.top + h * k), Pk.stroke(Pk.dark(a, 0.12), 2));
  }
  c.drawLine(Offset(r.left + w * 0.3 - 4, r.top), Offset(r.right + 4, r.top), Pk.stroke(b, 2));
  for (final x in [r.left, r.right - w * 0.3]) {
    c.drawCircle(Offset(x, r.bottom - 2), 2.5, Pk.fill(b));
  }
}

