void _palaceDistant(Canvas c, double ov, double t) {
  final wall = Pk.mix(const Color(0xFFBFB6A6), const Color(0xFFFFF4E0), ov);
  final roof = Pk.mix(const Color(0xFF6E6A70), const Color(0xFF3E5AA8), ov);
  final gold = Pk.mix(const Color(0xFF9A8C7A), _gold, ov);
  c.drawRect(const Rect.fromLTWH(70, 70, 260, 66), Pk.fill(wall));
  for (var i = 0; i < 11; i++) {
    final win = Rect.fromLTWH(80 + i * 22.6, 84, 10, 16);
    c.drawRRect(RRect.fromRectAndCorners(win, topLeft: const Radius.circular(5), topRight: const Radius.circular(5)), Pk.fill(Pk.mix(const Color(0xFF6E7A80), const Color(0xFF8ED8FF), ov)));
    c.drawRect(Rect.fromLTWH(80 + i * 22.6, 110, 10, 16), Pk.fill(Pk.mix(const Color(0xFF6E7A80), const Color(0xFF8ED8FF), ov)));
  }
  c.drawRect(const Rect.fromLTWH(66, 66, 268, 5), Pk.fill(gold));
  c.drawRect(const Rect.fromLTWH(170, 50, 60, 86), Pk.fill(Pk.light(wall, 0.2)));
  final dome = Path()
    ..moveTo(166, 52)
    ..quadraticBezierTo(200, 6, 234, 52)
    ..close();
  c.drawPath(dome, Pk.fill(roof));
  c.drawLine(const Offset(200, 24), const Offset(200, 12), Pk.stroke(gold, 2));
  c.drawCircle(const Offset(200, 10), 3, Pk.fill(gold));
  for (final x in [70.0, 314.0]) {
    c.drawRect(Rect.fromLTWH(x, 56, 16, 80), Pk.fill(Pk.dark(wall, 0.06)));
    Pk.poly(c, [Offset(x - 3, 56), Offset(x + 8, 38), Offset(x + 19, 56)], Pk.fill(roof));
  }
}

void _palaceFront(Canvas c, double ov, double t) {
  final wall = Pk.mix(const Color(0xFFBFB6A6), const Color(0xFFFFF4E0), ov);
  final gold = Pk.mix(const Color(0xFF9A8C7A), _gold, ov);
  final roof = Pk.mix(const Color(0xFF6E6A70), const Color(0xFF3E5AA8), ov);
  c.drawRect(const Rect.fromLTWH(0, 30, 400, 104), Pk.fill(wall));
  c.drawRect(const Rect.fromLTWH(0, 26, 400, 6), Pk.fill(gold));
  for (var i = 0; i < 9; i++) {
    if (i == 4) continue;
    final x = 14 + i * 44.0;
    final win = Rect.fromLTWH(x, 44, 18, 30);
    c.drawRRect(RRect.fromRectAndCorners(win, topLeft: const Radius.circular(9), topRight: const Radius.circular(9)), Pk.fill(Pk.mix(const Color(0xFF6E7A80), const Color(0xFF8ED8FF), ov)));
    c.drawRect(Rect.fromLTWH(x - 2, 74, 22, 3), Pk.fill(gold));
    c.drawRect(Rect.fromLTWH(x, 90, 18, 26), Pk.fill(Pk.mix(const Color(0xFF6E7A80), const Color(0xFF8ED8FF), ov)));
  }
  Pk.poly(c, const [Offset(140, 28), Offset(200, -6), Offset(260, 28)], Pk.fill(roof));
  c.drawRect(const Rect.fromLTWH(0, 132, 400, 4), Pk.fill(Pk.dark(wall, 0.15)));
}

void _throneHall(Canvas c, double ov, double t) {
  final stone = Pk.mix(const Color(0xFFB8B0A4), const Color(0xFFF6EAD8), ov);
  final gold = Pk.mix(const Color(0xFF9A8C7A), _gold, ov);
  for (final x in [12.0, 88.0, 290.0, 366.0]) {
    Pk.box(c, Rect.fromLTWH(x, 10, 22, 156), stone, radius: 1);
    c.drawRect(Rect.fromLTWH(x - 3, 10, 28, 6), Pk.fill(gold));
    c.drawRect(Rect.fromLTWH(x - 3, 160, 28, 6), Pk.fill(gold));
  }
  c.drawRect(const Rect.fromLTWH(0, 4, 400, 6), Pk.fill(gold));
}

void _libraryWall(Canvas c, double ov, double t) {
  final wood = Pk.mix(const Color(0xFF8C7E6C), const Color(0xFF8B5E3C), ov);
  c.drawRect(const Rect.fromLTWH(0, 110, 400, 56), Pk.fill(wood));
  for (var i = 0; i < 10; i++) {
    c.drawRect(Rect.fromLTWH(6 + i * 40.0, 116, 30, 42), Pk.stroke(Pk.dark(wood, 0.25), 1.5));
  }
  c.drawRect(const Rect.fromLTWH(0, 106, 400, 5), Pk.fill(Pk.dark(wood, 0.2)));
}

void _grandHall(Canvas c, double ov, double t) {
  final gold = Pk.mix(const Color(0xFF8A7E78), _gold, ov);
  for (var i = 0; i < 3; i++) {
    final win = Rect.fromLTWH(52 + i * 112.0, 18, 72, 132);
    final p = _archPath(win, 0.5);
    c.drawPath(_archPath(win.inflate(5), 0.5), Pk.fill(gold));
    c.drawPath(p, _vgrad(win, Pk.mix(const Color(0xFF3A3A4A), const Color(0xFF14123A), ov), Pk.mix(const Color(0xFF5A5A6A), const Color(0xFF3A2A6E), ov)));
    c.save();
    c.clipPath(p);
    _stars(c, win, 12, ov, t, i * 13);
    c.restore();
    c.drawLine(Offset(win.center.dx, win.top + 4), Offset(win.center.dx, win.bottom), Pk.stroke(gold, 2));
  }
  for (final x in [20.0, 140.0, 252.0, 368.0]) {
    Pk.box(c, Rect.fromLTWH(x, 8, 14, 158), Pk.mix(const Color(0xFFB8B0A4), const Color(0xFFFFF0D0), ov), radius: 1);
    c.drawRect(Rect.fromLTWH(x - 3, 8, 20, 6), Pk.fill(gold));
  }
  c.drawRect(const Rect.fromLTWH(0, 2, 400, 6), Pk.fill(gold));
}

